/* ============================================================
   ABA HABILIDADES DO ESTUDO
   ============================================================
   Os pontos de entrada da ficha atual continuam: filtros por efeito, busca,
   Funcionamento Básico, os grupos na ordem de GRUPOS e as sub-abas por
   Classe. O que muda é a LINHA:
     uma linha só, de altura única (2026-10-14): nome, estado ligado (◆),
                 marcas e, na busca, onde casou
     à direita   controles curtos, com "Não Desconta PE" quando o controle
                 aplica o efeito sem cobrar
   A descrição do estudo saiu da linha: ela está na consulta ("Em Resumo") e
   entra no índice da busca. Um valor entre as marcas ("−10 PE") vai sem o
   ponto separador, com o sinal escrito.
   Clicar na linha abre a consulta, que fica POR CIMA da área: a lista não
   se move nem muda de largura.
   ============================================================ */
import React, { useMemo, useState } from "react";
import { Search, Star, X, ZapOff, BookOpenText, ChevronRight } from "lucide-react";
import { GRUPOS, FILTROS_HABILIDADE, correspondeFiltroHabilidade, estaLigado } from "./ponte";
import { buscar } from "./repertorio";
import { semAcento } from "./util";
import { Controle, nomeDoControle, estadoDaLinha, navegarLista } from "./pecas";
import { CHAVE_GOLPE, exemploDoItem as descricaoDe, propriedadesDoGolpe } from "./efeitos-dados";
import { ativaPorPreparacao } from "./g2-dados";

const GRUPO_IDS = new Set(GRUPOS.map((g) => g.id));

/* Um controle é CURTO quando cabe na linha: interruptor, passo, ou até
   três opções. O resto mora só na consulta. */
export function ehCurto(c) {
  if (c.partes) return c.partes.length <= 3;
  const e = c.estados[0];
  if (e.tipo === "bool" || e.tipo === "faixa") return true;
  return (e.opcoesVisiveis ?? e.opcoes ?? []).length <= 3;
}

/* O controle aplica o efeito sem cobrar, mas a regra fala em gastar PE:
   isso precisa estar escrito no ponto de uso.
   ⚠ CORRIGIDO NA RODADA 7: a rodada 6 tirava daqui todo estado com
   `custoPE`, supondo que o motor cobrasse. Não cobra: o `custoPE` do
   estado só é MOSTRADO (Canalizar em Golpe, Canalização Máxima). A única
   cobrança da sessão é a do Invencível sob o Sol (`alteraEstadoCombate`). */
const FALA_DE_PE = /gast\w*\s+(?:\d+\s*)?(?:PE|pontos? de energia)|gastar\s+uma\s+quantidade\s+de\s+(?:PE|pontos? de energia)|\d+\s?PE\b/i;
const COBRADO_PELA_SESSAO = new Set(["invencivelSobOSol"]);
export function naoDescontaPE(c, item) {
  if (c.estados.some((s) => COBRADO_PELA_SESSAO.has(s.id))) return false;
  return c.estados.some((s) => s.custoPE != null) || /\bPE\b/.test(c.rotulo ?? "") || FALA_DE_PE.test(String(item?.texto ?? ""));
}

/* O nome do controle sem repetir o nome do item ("Cobrir-se · PE Gasto" vira
   "PE Gasto") nem a opção que o botão já mostra ("Duelando · Uma Arma, Mão
   Livre" vira "Duelando"). */
export function rotuloCurto(c, item) {
  const nome = nomeDoControle(c);
  if (nome === item?.nome) return null;
  const prefixo = `${item?.nome} · `;
  const sem = nome.startsWith(prefixo) ? nome.slice(prefixo.length) : nome;
  const i = sem.lastIndexOf(" · ");
  if (i > 0) {
    const fim = sem.slice(i + 3);
    const botoes = [...(c.partes ?? []), ...(c.estados[0]?.opcoesVisiveis ?? c.estados[0]?.opcoes ?? []).map((o) => o.label)];
    if (botoes.includes(fim)) return sem.slice(0, i);
  }
  return sem;
}

function Trecho({ t }) {
  if (!t) return null;
  return (
    <span className="e-trecho">
      {t.cortadoAntes && "…"}
      {t.partes.map((p, i) => (p.marca ? <mark key={i}>{p.t}</mark> : <span key={i}>{p.t}</span>))}
      {t.cortadoDepois && "…"}
    </span>
  );
}
const ONDE = { nome: "No Nome", "opção": "Na Escolha", texto: "No Texto" };

/* Uma marca que é VALOR (com sinal e número, "-10 PE"): sem o ponto separador,
   e com o sinal de menos tipográfico, como todo número da ficha. */
const EH_VALOR = /^[+\-−]\s?\d/;
function Marca({ t }) {
  const valor = EH_VALOR.test(t);
  return <span className="e-marca" data-valor={valor ? "" : undefined}>{valor ? t.replace(/^-/, "−") : t}</span>;
}

/* O ACESSO DE HABILIDADES aos grupos que já têm Preparação (consolidação ampliada, 2026-10-16). Nada de caminho imediato: o
   controle de quem já tem custo, limite, uso ou confirmação (Ataque Concentrado, Concentrar Aura, Espírito Incansável, Postura,
   Golpe Especial e os outros) é uma ação discreta. Desligado, "Ativar" abre a Preparação NO PAINEL sem gravar nada. Ativo, "Abrir"
   leva ao detalhe, onde o Ajustar diz o que a habilidade realmente permite. O filho (o Incansável) vai ao grupo certo, o do Espírito de Luta. */
export function EntradaDoPreparo({ o, g, onAbrirPainel }) {
  const ativo = g.ativos.some((a) => a.chave === o.chave);
  const rotulo = ativo ? "Abrir" : "Ativar";
  const aoClicar = () => {
    if (ativo) g.acoes.abrirNoPainel(o.chave);
    else if (!g.acoes.abrirPreparo(o)) return;
    onAbrirPainel?.();
  };
  return <button type="button" className="afty-botao e-botao e-ativar-preparo" data-preparo-entrada={o.chave} title={`${rotulo} ${o.nome} pelos Efeitos`} aria-label={`${rotulo} ${o.nome}`} onClick={aoClicar}>{rotulo}</button>;
}

function Linha({ e, m, g, porChave, onAbrirPainel, consultada, onAbrir, rotuloSub, achado }) {
  /* Cada controle do item vai para o grupo dele: com Preparação, vira a entrada discreta (uma por grupo). Sem ela, segue o controle de hoje. */
  const roteados = new Map();
  const cs = [];
  for (const c of m.controlesPorDono.get(e.chave) ?? []) {
    const gr = g.grupoDoEstado.get(c.estados[0].id);
    const o = gr ? porChave.get(gr.chave) : null;
    if (o && ativaPorPreparacao(o)) roteados.set(o.chave, o);
    else if (ehCurto(c)) cs.push(c);
  }
  /* Interruptor com o mesmo nome do item: "◆ Ligado", sem repetir o nome. */
  /* O Golpe Especial tem marcas fora dos estados: a linha diz as propriedades marcadas, nas duas casas do montador. */
  const props = e.chave === CHAVE_GOLPE && m.combate ? propriedadesDoGolpe(m.sessao).map((x) => x.texto) : [];
  const estBruto = props.length ? props.join(", ") : estadoDaLinha(e, m);
  const est = estBruto === e.nome ? "Ligado" : estBruto;
  const fixado = m.fixados.includes(e.chave);
  const marcas = (e.tags ?? []).map((t) => t.label).filter((l) => l && l !== rotuloSub);
  return (
    <div className="afty-linha e-linha" data-consultada={consultada ? "sim" : undefined}>
      <button type="button" className="e-estrela" aria-pressed={fixado} onClick={() => m.fixar(e.chave)}
        aria-label={fixado ? `Tirar ${e.nome} dos Fixados` : `Fixar ${e.nome}`} title={fixado ? "Tirar dos Fixados" : "Fixar"}>
        <Star aria-hidden="true" fill={fixado ? "currentColor" : "none"} />
      </button>
      <button type="button" className="e-linha-corpo" data-chave={e.chave} onClick={() => onAbrir(e.chave)} aria-haspopup="dialog"
        aria-label={`${e.nome}. Consultar a regra`}>
        <span className="e-linha-topo">
          <span className="e-nome-item" title={e.nome}>{e.nome}</span>
          {est && <span className="e-ativo">◆ {est}</span>}
          {achado && <span className="e-onde" data-onde={achado.onde}>{ONDE[achado.onde]}</span>}
          {marcas.length > 0 && <span className="e-metas" title={marcas.map((t) => t.replace(/^-(?=\d)/, "−")).join(" · ")}>{marcas.map((t) => <Marca key={t} t={t} />)}</span>}
        </span>
      </button>
      {(cs.length > 0 || roteados.size > 0) && (
        <div className="e-linha-ctrl">
          {[...roteados.values()].map((o) => <span key={o.chave} className="e-ctrl"><EntradaDoPreparo o={o} g={g} onAbrirPainel={onAbrirPainel} /></span>)}
          {cs.map((c) => (
            <span key={c.id} className="e-ctrl">
              {rotuloCurto(c, e) && <span className="e-ctrl-rotulo" title={rotuloCurto(c, e)}>{rotuloCurto(c, e)}</span>}
              <Controle c={c} m={m} compacto />
              {naoDescontaPE(c, e) && <span className="e-pe" title="O controle aplica o efeito. O PE da regra é gasto à parte, na Energia."><ZapOff aria-hidden="true" />Não Desconta PE</span>}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

function subsDe(lista) {
  const mapa = new Map();
  for (const i of lista) {
    if (!i.sub) continue;
    if (!mapa.has(i.sub.id)) mapa.set(i.sub.id, { ...i.sub, quantos: 0 });
    mapa.get(i.sub.id).quantos += 1;
  }
  const subs = [...mapa.values()];
  return subs.length > 1 ? subs : [];
}

function Grupo({ grupo, lista, m, g, porChave, onAbrirPainel, consultada, onAbrir, filtrando, achados }) {
  const subs = useMemo(() => subsDe(lista), [lista]);
  const [ativa, setAtiva] = useState(null);
  if (!lista.length) return null;
  const efetiva = filtrando ? null : (subs.some((s) => s.id === ativa) ? ativa : subs[0]?.id ?? null);
  const visiveis = efetiva ? lista.filter((i) => i.sub?.id === efetiva) : lista;
  const rotuloAtivo = subs.find((s) => s.id === efetiva)?.label ?? null;
  return (
    <section className="afty-card e-grupo" aria-label={grupo.label}>
      <header className="e-grupo-topo">
        <h2 className="afty-card-titulo e-grupo-titulo">{grupo.label}<small>{lista.length}</small></h2>
        {subs.length > 0 && !filtrando && (
          <div className="e-subabas" role="tablist" aria-label={`Divisões de ${grupo.label}`}>
            {subs.map((s) => (
              <button key={s.id} type="button" role="tab" className="e-subaba" aria-selected={s.id === efetiva} onClick={() => setAtiva(s.id)}>
                {s.label}<small>{s.quantos}</small>
              </button>
            ))}
          </div>
        )}
      </header>
      <div className="e-grupo-lista">
        {visiveis.map((e) => (
          <Linha key={e.chave} e={e} m={m} g={g} porChave={porChave} onAbrirPainel={onAbrirPainel} consultada={consultada === e.chave} onAbrir={onAbrir} rotuloSub={rotuloAtivo} achado={achados?.get(e.chave)} />
        ))}
      </div>
    </section>
  );
}

export default function Habilidades({ m, g, consultada, onAbrir, onAbrirPainel }) {
  const [termo, setTermo] = useState("");
  const porChave = useMemo(() => new Map(g.opcoes.map((o) => [o.chave, o])), [g.opcoes]);
  const [efeito, setEfeito] = useState("todos");
  const { rep } = m.pacote;
  const itens = useMemo(() => rep.todas.filter((e) => GRUPO_IDS.has(e.grupo)), [rep]);
  const funcionamentos = useMemo(() => rep.todas.filter((e) => e.tipo === "funcionamento"), [rep]);
  /* A descrição do estudo saiu da linha, mas continua na busca: ela entra no índice junto do texto da regra. */
  const indice = useMemo(() => [...itens, ...funcionamentos].map((e) => {
    const d = descricaoDe(e);
    return d?.texto ? { ...e, busca: `${e.busca} \n ${semAcento(d.texto)}` } : e;
  }), [itens, funcionamentos]);
  const achados = useMemo(() => (termo.trim() ? new Map(buscar(indice, termo).map((r) => [r.e.chave, r])) : null), [indice, termo]);
  const passaEfeito = (e) => efeito === "todos" || correspondeFiltroHabilidade({ id: e.id, nome: e.nome, texto: e.texto, opcoes: e.opcoes }, efeito, "");
  const filtrados = itens.filter((e) => passaEfeito(e) && (!achados || achados.has(e.chave)));
  const funcsVisiveis = funcionamentos.filter((e) => passaEfeito(e) && (!achados || achados.has(e.chave)));
  const filtrando = !!achados || efeito !== "todos";
  const noNome = achados ? [...achados.values()].filter((r) => r.onde === "nome" && filtrados.concat(funcsVisiveis).some((e) => e.chave === r.e.chave)).length : 0;
  const noTexto = achados ? filtrados.length + funcsVisiveis.length - noNome : 0;
  const total = itens.length;

  return (
    <div className="e-habilidades" ref={m.listaRef} onKeyDown={navegarLista(m.listaRef, ".e-linha-corpo")} data-lista data-rolavel="lista"
      onScroll={(ev) => ev.currentTarget.toggleAttribute("data-rolada", ev.currentTarget.scrollTop > 2)}>
      <div className="e-ferramentas">
        <label className="e-busca">
          <Search aria-hidden="true" />
          <input className="afty-campo" type="search" value={termo} data-filtro placeholder={`Buscar em ${total} habilidades, pelo nome ou pelo texto`}
            onChange={(ev) => setTermo(ev.target.value)} onKeyDown={(ev) => { if (ev.key === "Escape") setTermo(""); }} aria-label="Buscar habilidades pelo nome ou pelo texto" />
          {termo && <button type="button" className="e-limpar" onClick={() => setTermo("")} aria-label="Limpar a busca"><X aria-hidden="true" /></button>}
        </label>
        {achados && (
          <p className="e-contagem" aria-live="polite">
            <span className="e-contagem-total"><b>{filtrados.length + funcsVisiveis.length}</b> {filtrados.length + funcsVisiveis.length === 1 ? "Resultado" : "Resultados"}</span>
            <span data-onde="nome">No Nome <b>{noNome}</b></span><span data-onde="texto">No Texto <b>{noTexto}</b></span>
          </p>
        )}
        <div className="e-efeitos" role="radiogroup" aria-label="Filtrar por efeito">
          <span className="e-efeitos-rotulo">Efeito</span>
          {[{ id: "todos", label: "Todos" }, ...FILTROS_HABILIDADE].map((f) => (
            <button key={f.id} type="button" role="radio" aria-checked={efeito === f.id} className="e-efeito" onClick={() => setEfeito(f.id)}>{f.label}</button>
          ))}
        </div>
      </div>

      {funcsVisiveis.map((f) => (
        <button key={f.chave} type="button" className="afty-card e-tecnica" data-chave={f.chave} data-consultada={consultada === f.chave ? "sim" : undefined} onClick={() => onAbrir(f.chave)}>
          <BookOpenText aria-hidden="true" /><span className="e-tecnica-nome">{f.nome}</span>
          {achados?.get(f.chave) && <><span className="e-onde">{ONDE[achados.get(f.chave).onde]}</span><Trecho t={achados.get(f.chave).trecho} /></>}
          <ChevronRight aria-hidden="true" className="e-tecnica-seta" />
        </button>
      ))}

      {GRUPOS.map((grupo) => (
        <Grupo key={grupo.id} g={g} grupo={grupo} porChave={porChave} onAbrirPainel={onAbrirPainel} lista={filtrados.filter((e) => e.grupo === grupo.id)} m={m} consultada={consultada} onAbrir={onAbrir} filtrando={filtrando} achados={achados} />
      ))}

      {filtrados.length === 0 && funcsVisiveis.length === 0 && (
        <div className="e-vazio" role="status">
          <p>Nenhuma habilidade para <b>{termo ? `“${termo}”` : FILTROS_HABILIDADE.find((f) => f.id === efeito)?.label}</b></p>
          <button type="button" className="afty-botao e-botao" onClick={() => { setTermo(""); setEfeito("todos"); }}>Limpar</button>
        </div>
      )}
      <div className="e-respiro" aria-hidden="true" />
    </div>
  );
}

export { estaLigado };

/* ============================================================
   HISTÓRICO DA SESSÃO, SOB DEMANDA (fechamento do G2, 2026-10-16)
   ============================================================
   Os DADOS são os da mesa (`mesa.eventos` e `mesa.ativacoes`, os que o motor do v2 já grava), e o VERBO de estornar é o do v2 (`desfazer`, pelo
   `m.historicoProps.onDesfazer`) com a conferência dele (`podeDesfazer`). Não existe um segundo histórico calculado do texto da tela. O componente
   `Historico.jsx` do v2 não entra por três motivos: não mostra o horário do evento, promete "Desfazer" onde só o PE volta, e não filtra.
   O resto (o resumo de cada tipo de evento) segue o do v2, com a mesma redação, mais o horário real, o dano do Sacrifício que o Golpe também
   causa e o uso registrado.

   SOB DEMANDA: um acesso discreto ao pé dos Ativos (completa e compacta) e no menu do cabeçalho abrem um painel flutuante (`Flutuante`, como os
   outros do estudo: Esc fecha, o foco volta a quem abriu). Consultar, filtrar, abrir e fechar NÃO tocam a mesa, e o painel fica POR CIMA: o efeito aberto,
   a seleção e a rolagem de quem abriu continuam onde estavam.

   ESTORNAR PE NÃO É DESFAZER O EFEITO. O estorno devolve só os PE do gasto (a Energia, e o PE Temporário só na mesma rodada). Não desliga estado, não
   devolve um uso, não remove concessão de PV Temporário e não desfaz o dano do Sacrifício. O rótulo diz "Estornar PE", e o hover diz o resto.
   Onde o mecanismo não permite (a cobrança que o próprio motor faz ao ligar o Invencível sob o Sol), o botão é "Sem Estorno".
   ============================================================ */
import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, History, Undo2, X } from "lucide-react";
import { podeDesfazer } from "./mesa-verbos";
import { Flutuante } from "./pecas";

export const HistoricoCtx = createContext(null);

const FILTROS = [
  { id: "tudo", rotulo: "Todos", serve: () => true },
  { id: "gastos", rotulo: "Gastos e Usos", serve: (ev) => ["gasto", "ativacao", "desfazer", "uso"].includes(ev.tipo) },
  { id: "rolagens", rotulo: "Rolagens", serve: (ev) => ev.tipo === "rolagem" },
  { id: "vida", rotulo: "Vida e Alma", serve: (ev) => ev.tipo === "dano" || ev.tipo === "cura" },
  { id: "rodadas", rotulo: "Rodadas", serve: (ev) => ev.tipo === "rodada" || ev.tipo === "info" },
];

const sinal = (v) => `${v > 0 ? "+" : "−"}${Math.abs(v)}`;
const doisDigitos = (n) => String(n).padStart(2, "0");
/** O horário REAL do evento (`ev.ts`, gravado quando ele aconteceu). Com a data quando não é de hoje. */
export function horaDoEvento(ts, agora = new Date()) {
  const d = new Date(ts);
  const hora = `${doisDigitos(d.getHours())}:${doisDigitos(d.getMinutes())}:${doisDigitos(d.getSeconds())}`;
  const hoje = d.toDateString() === agora.toDateString();
  return hoje ? hora : `${doisDigitos(d.getDate())}/${doisDigitos(d.getMonth() + 1)} ${hora}`;
}

/** O que o evento diz, com a redação do v2 (`Historico.jsx`), mais o que o protótipo registra além dele. */
export function resumoDoEvento(ev) {
  if (ev.tipo === "rolagem") return `${ev.r.rotulo}${ev.r.detalhe ? ` · ${ev.r.detalhe}` : ""}${ev.deNovo ? " · de novo" : ""}`;
  if (ev.tipo === "ativacao") return `${ev.nome} · ${ev.estado ? "ligou" : "usou"} · ${ev.custo} PE`;
  if (ev.tipo === "gasto") return `${ev.nome} · gastou ${ev.custo} PE${ev.dano > 0 ? ` e ${ev.dano} de dano` : ""}`;
  if (ev.tipo === "desfazer") return `${ev.nome} · estorno · ${ev.devolvido} PE de volta`;
  if (ev.tipo === "uso") return `${ev.nome} · uso registrado${ev.usos ? ` · restam ${ev.usos.restam} de ${ev.usos.max}` : ""}`;
  if (ev.tipo === "dano" || ev.tipo === "cura") {
    const partes = [];
    if (ev.mudou.casca) partes.push(`Temporário ${sinal(ev.mudou.casca)}`);
    if (ev.mudou.vida) partes.push(`Vida ${sinal(ev.mudou.vida)}`);
    if (ev.mudou.alma) partes.push(`Alma ${sinal(ev.mudou.alma)}`);
    return `${ev.tipo === "dano" ? "Dano" : "Cura"}${ev.naAlma ? " na Alma" : ""} ${ev.valor}: ${partes.join(" · ") || "sem mudança"}${ev.tipo === "dano" && !ev.naAlma ? " · sem abater RD" : ""}`;
  }
  if (ev.tipo === "rodada") {
    const n = ev.nota;
    /* O Buff de Mesa (a fonte externa registrada) chega sem `nome` no evento do v2: o tipo que o evento traz diz o que foi, sem inventar um nome. */
    return `Rodada ${n.rodada} · Expirou: ${n.expirou.length ? n.expirou.map((x) => x.nome || x.tipo || "Efeito").join(", ") : "nada"}${n.cobrado.length ? ` · Cobrado: ${n.cobrado.map((c) => `${c.nome} −${c.valor} PE`).join(", ")}` : ""}`;
  }
  if (ev.tipo === "info") return ev.texto;
  return ev.tipo;
}

/** De onde saiu o PE de um gasto ("Energia 3 · Temporário 1"), para o estorno não surpreender. */
const origemDoPago = (pago) => {
  if (!pago) return null;
  const casca = Object.values(pago.casca ?? {}).reduce((a, v) => a + v, 0);
  const partes = [pago.reserva > 0 ? `Energia ${pago.reserva}` : null, casca > 0 ? `Temporário ${casca}` : null].filter(Boolean);
  return partes.length ? partes.join(" · ") : null;
};

const AJUDA_ESTORNO = "Devolve só os PE deste gasto. O efeito, os usos, o PV Temporário e o dano do Sacrifício continuam como estão.";

function Entrada({ ev, mesa, onEstornar }) {
  const at = ev.ativacaoId ? mesa.ativacoes[ev.ativacaoId] : null;
  const gasta = at && (ev.tipo === "ativacao" || ev.tipo === "gasto");
  const pode = gasta ? podeDesfazer(mesa, at.id) : null;
  const origem = gasta ? origemDoPago(at.pago) : null;
  return (
    <li className="h-hist-item" data-tipo={ev.tipo} data-evento={ev.id} data-estornado={gasta && at.desfeita ? "sim" : undefined}>
      <span className="h-hist-meta">
        <b>R{ev.rodada}</b>
        <time dateTime={new Date(ev.ts).toISOString()} title={new Date(ev.ts).toLocaleString("pt-BR")} data-hora={ev.ts}>{horaDoEvento(ev.ts)}</time>
      </span>
      <span className="h-hist-texto">
        <span data-resumo>{resumoDoEvento(ev)}</span>
        {origem && <small className="h-hist-origem">{origem}</small>}
        {ev.tipo === "rolagem" && <small className="h-hist-origem">{ev.r.formula} = <b>{ev.r.total}</b></small>}
        {ev.tipo === "desfazer" && ev.limites?.length > 0 && (
          <ul className="h-hist-limites">{ev.limites.map((l) => <li key={l}><AlertTriangle aria-hidden="true" />{l}</li>)}</ul>
        )}
      </span>
      {gasta && (
        <button type="button" className="m-botao h-hist-acao" disabled={!pode.ok} onClick={() => onEstornar(at.id)} data-estornar={at.id}
          title={at.desfeita ? "Este gasto já foi estornado" : pode.ok ? AJUDA_ESTORNO : pode.motivo}
          aria-label={`${at.desfeita ? "Estornado" : pode.ok ? "Estornar PE" : "Sem Estorno"}: ${ev.nome}`}>
          <Undo2 aria-hidden="true" />{at.desfeita ? "Estornado" : pode.ok ? "Estornar PE" : "Sem Estorno"}
        </button>
      )}
    </li>
  );
}

/** A âncora do painel, sempre DENTRO da janela: o botão que o abriu mora numa lista que rola, e ao redimensionar (ou rolar) ele pode ficar fora de vista.
 *  O `Flutuante` posiciona pelo retângulo da âncora, e fora de vista o painel sairia da janela: aqui o retângulo é preso à janela. */
const ancoraNaJanela = (el) => ({
  contains: (n) => el?.contains?.(n),
  getBoundingClientRect() {
    const r = el.getBoundingClientRect();
    const alto = window.innerHeight;
    const topo = Math.min(Math.max(r.top, 8), alto - 44);
    const base = Math.min(Math.max(r.bottom, topo + 28), alto - 8);
    return { top: topo, bottom: base, left: r.left, right: r.right, width: r.width, height: base - topo, x: r.left, y: topo };
  },
});

/** O painel. `filtro` e `onFiltro` moram em quem abre (o painel pode ser refeito ao redimensionar a janela sem perder o filtro). */
export function HistoricoPainel({ ancora, m, nome, filtro, onFiltro, onFechar }) {
  const mesa = m.mesa;
  const ancoraPresa = useMemo(() => ancoraNaJanela(ancora), [ancora]);
  const eventos = mesa.eventos;
  const ativo = FILTROS.find((f) => f.id === filtro) ?? FILTROS[0];
  const lista = eventos.filter(ativo.serve);
  /* Estornar uma vez só: o clique repetido (ou um segundo clique antes de a tela refletir o primeiro) não estorna de novo. A conferência da ativação
     (`podeDesfazer`) é refeita pelo próprio verbo na mesa que estiver valendo. */
  const emCurso = useRef(new Set());
  const estornar = (id) => {
    if (emCurso.current.has(id)) return;
    emCurso.current.add(id);
    m.historicoProps.onDesfazer(id);
    setTimeout(() => emCurso.current.delete(id), 500);
  };
  return (
    <Flutuante ancora={ancoraPresa} onFechar={onFechar} largura={460} rotulo="Histórico da Sessão" classe="h-hist-painel">
      <section className="h-hist" data-historico aria-label="Histórico da Sessão" data-mesa={m.mesaId}>
        <header className="h-hist-topo">
          <History aria-hidden="true" />
          <h2>Histórico<small>{nome}</small></h2>
          <button type="button" className="e-icone" onClick={onFechar} aria-label="Fechar o Histórico" data-historico-fechar><X aria-hidden="true" /></button>
        </header>
        <div className="h-hist-filtros m-seg" role="group" aria-label="Quais eventos">
          {FILTROS.map((f) => {
            const n = eventos.filter(f.serve).length;
            return (
              <button key={f.id} type="button" className="m-seg-op" aria-pressed={f.id === ativo.id} disabled={!n && f.id !== "tudo"} onClick={() => onFiltro(f.id)} data-historico-filtro={f.id}>
                {f.rotulo}<small>{n}</small>
              </button>
            );
          })}
        </div>
        <ol className="h-hist-lista" aria-label="Eventos, do mais recente ao mais antigo" data-historico-lista>
          {lista.length === 0 && <li className="h-hist-vazio">Nada Aconteceu Ainda</li>}
          {lista.map((ev) => <Entrada key={ev.id} ev={ev} mesa={mesa} onEstornar={estornar} />)}
        </ol>
      </section>
    </Flutuante>
  );
}

/** O acesso discreto, ao pé dos Ativos e da lista do painel: um botão de texto com o total. Nada aberto, nada empilhado. */
export function AcessoAoHistorico({ onde }) {
  const ctx = useContext(HistoricoCtx);
  if (!ctx) return null;
  return (
    <div className="h-acesso" data-historico-acesso={onde}>
      <button type="button" className="e2-toggle" aria-haspopup="dialog" onClick={(e) => ctx.abrir(e.currentTarget)} data-historico-abrir>
        <History aria-hidden="true" />Histórico<small>{ctx.total}</small>
      </button>
    </div>
  );
}

/** O tamanho da janela, para o painel (posicionado uma vez) ser refeito quando ela é redimensionada, sem fechar. */
export function useTamanhoDaJanela() {
  const [t, setT] = useState(() => `${window.innerWidth}x${window.innerHeight}`);
  useEffect(() => {
    const f = () => setT(`${window.innerWidth}x${window.innerHeight}`);
    window.addEventListener("resize", f);
    return () => window.removeEventListener("resize", f);
  }, []);
  return t;
}

