source:
/* ============================================================
   G2 · PREPARAÇÃO E AJUSTE (Entrega 1: o Ataque Concentrado)
   ============================================================
   PREPARAÇÃO  o que escolher antes de ativar, o custo dessa escolha, o que
               muda nos números e só então Confirmar. Nada toca a sessão até
               confirmar: o rascunho mora no estado de tela (`catalogo.preparo`).
   AJUSTE      no detalhe do cartão ativo, o passo muda um rascunho, e a
               diferença aparece antes de confirmar. Subir cobra só a diferença
               do acumulado. Descer não devolve.
   Tudo o que tem valor sai do motor:
     - o controle e o teto: `o.grupo.controles[0]`, `max(derived)`
       (3 com Surto de Ação, 1 sem ele);
     - o custo: `estado.custoPE(v)`, o acumulado 1, 3 e 4 PE;
     - o que muda: o derive com o rascunho contra o derive de agora.
   ============================================================ */
import React, { useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, Hand, Minus, Plus, Repeat, Zap } from "lucide-react";
import { energiaDisponivel } from "./mesa-verbos";
import { Controle } from "./pecas";
import { compararTudo, custoAntes, derivarCom, estaLigado, maxDe, verificacoes } from "./efeitos-dados";
import { GastarNaEnergia } from "./Gestor";
import { NOME_DO_FILHO, custoDe, custoEmJogo, preparoDe, rotuloDaFaixa } from "./g2-dados";
import { GanhaPerde, SemNumeros } from "./PecasG2";
import { planoDoPreparo, previaDoPlano, raizDo, rascunhoInicial, saneia } from "./g2-preparo";
import { planoDoGolpe, previaDoGolpe, rascunhoDoGolpe } from "./g2-golpe";

const inteiro = (v) => Math.max(0, Math.trunc(Number(v) || 0));

/** O que a ficha diz deste controle: o estado, o rótulo, o teto e o custo de cada passo. */
export function faixaDoPiloto(gr, derived) {
  const c = gr.controles[0];
  const e = c.estados[0];
  const max = inteiro(maxDe(e, derived));
  const passos = Array.from({ length: max }, (_, i) => i + 1);
  return { c, e, max, passos, rotulo: rotuloDaFaixa(e, gr), custo: (v) => inteiro(custoDe(e, v)) };
}

/* O que muda nos números com o rascunho, pelo motor. Dois derives por escolha. */
function usePrevia(m, e, valor) {
  return useMemo(() => {
    if (valor == null) return [];
    const base = m.sessao;
    const antes = derivarCom(m.ficha, base);
    const depois = derivarCom(m.ficha, { ...base, combate: { ...(base.combate ?? {}), [e.id]: valor } });
    return compararTudo(depois, antes);
  }, [m.ficha, m.sessao, e.id, valor]);
}

/* Por padrão, a Preparação do catálogo (o rascunho em `catalogo.preparo`).
   Reativar um encerrado usa a MESMA Preparação, com o rascunho dele: reativar
   é uma ativação nova, que mostra a escolha e o custo e cobra ao confirmar. */
export function PreparoG2({ o, g, m, valor: valorDe = undefined, onValor = null, onCancelar = null, onConfirmar = null, rotuloConfirmar = "Confirmar Ativação" }) {
  const f = faixaDoPiloto(o.grupo, m.derived);
  const bruto = valorDe !== undefined ? valorDe : g.tela.catalogo.preparo?.valor;
  const valor = Math.min(f.max, Math.max(1, inteiro(bruto) || 1));
  const custo = f.custo(valor);
  const disponivel = energiaDisponivel(m.sessao);
  const bloqueios = [...verificacoes(o, m).nao, ...(disponivel < custo ? [`Faltam ${custo - disponivel} PE`] : [])];
  const previa = usePrevia(m, f.e, valor);
  const escolher = onValor ?? ((n) => g.mudaCatalogo((c) => ({ preparo: { ...c.preparo, valor: n } })));
  const cancelar = onCancelar ?? (() => g.mudaCatalogo({ preparo: null }));
  const confirmar = onConfirmar ?? ((v) => g.acoes.confirmarAtivacao(o, v));
  /* O Confirmar à vista: o detalhe rola sozinho até ele quando a Preparação abre. */
  const botoes = useRef(null);
  useEffect(() => { botoes.current?.scrollIntoView({ block: "nearest" }); }, []);
  /* Um clique só: o segundo de um clique duplo não chega à mesa (2026-10-15).
     Se a confirmação não passar, o botão volta a valer. */
  const enviado = useRef(false);
  const aoConfirmar = () => {
    if (enviado.current) return;
    enviado.current = true;
    if (confirmar(valor) === false) enviado.current = false;
  };
  return (
    <div className="k-confirmar g2-preparo" data-ativando="">
      <h3 className="k-sub">Preparação</h3>
      <div className="g2-preparo-linha">
        <span className="x-ctrl-nome">{f.rotulo}</span>
        <span className="m-seg g2-escolha" role="radiogroup" aria-label={f.rotulo} data-preparo-intensidade>
          {f.passos.map((n) => (
            <button key={n} type="button" role="radio" className="m-seg-op" aria-checked={n === valor} data-valor={n} onClick={() => escolher(n)}>{n}</button>
          ))}
        </span>
      </div>
      <span className="x-custo-jogo" data-auto="" data-custo-preparo={custo}><Zap aria-hidden="true" />{custo ? `Desconta ${custo} PE da Energia ao Confirmar` : "Sem Custo"}</span>
      <h3 className="k-sub">Ao Confirmar</h3>
      <div className="g2-previa" data-previa>
        {previa.length ? <GanhaPerde chips={previa} /> : <span className="x-mesa">Sem Mudança nos Seus Números</span>}
      </div>
      {bloqueios.map((t) => <span key={t} className="x-atencao" data-bloqueio><AlertTriangle aria-hidden="true" />{t}</span>)}
      <span ref={botoes} className="x-linha">
        <button type="button" className="m-botao x-adicionar g2-primario" disabled={bloqueios.length > 0} onClick={aoConfirmar} data-confirmar>{rotuloConfirmar}</button>
        <button type="button" className="m-botao" onClick={cancelar} data-voltar-preparo>Voltar</button>
      </span>
    </div>
  );
}

/* O ajuste do cartão ativo. O passo muda o rascunho; a sessão só muda ao confirmar. */
export function AjusteG2({ a, g, m }) {
  const f = faixaDoPiloto(a.grupo, m.derived);
  const atual = inteiro(m.sessao.combate?.[f.e.id]);
  const [valor, setValor] = useState(atual);
  const enviado = useRef(false);
  useEffect(() => { setValor(atual); enviado.current = false; }, [atual]);
  const aoConfirmar = () => {
    if (enviado.current) return;
    enviado.current = true;
    if (g.acoes.confirmarAjuste(a, valor) === false) enviado.current = false;
  };
  const dif = f.custo(valor) - f.custo(atual);
  const disponivel = energiaDisponivel(m.sessao);
  const falta = dif > 0 && disponivel < dif ? dif - disponivel : 0;
  const bloqueios = [...(!m.combate ? ["Pede Em Combate"] : []), ...(falta ? [`Faltam ${falta} PE`] : [])];
  const mudou = valor !== atual;
  /* A confirmação do ajuste à vista quando ela aparece (a lista dos Ativos rola). */
  const pendente = useRef(null);
  useEffect(() => { if (mudou) pendente.current?.scrollIntoView({ block: "nearest" }); }, [mudou]);
  return (
    <div className="x-ctrl" data-ajuste>
      <span className="x-ctrl-nome">{f.rotulo}</span>
      <span className="x-ctrl-linha">
        <span className="m-passos">
          <button type="button" className="m-passo" aria-label={`${f.rotulo} menos 1`} disabled={valor <= 1} onClick={() => setValor(valor - 1)}><Minus aria-hidden="true" /></button>
          <span className="m-passos-valor" aria-live="polite" data-ajuste-valor={valor}>{valor}<small>/{f.max}</small></span>
          <button type="button" className="m-passo" aria-label={`${f.rotulo} mais 1`} disabled={valor >= f.max} onClick={() => setValor(valor + 1)}><Plus aria-hidden="true" /></button>
        </span>
        {!mudou && <span className="x-custo">Custo da {f.rotulo} {atual}: {f.custo(atual)} PE</span>}
      </span>
      {mudou && (
        <div ref={pendente} className="g2-ajuste" data-ajuste-pendente>
          {dif > 0
            ? <span className="x-custo-jogo" data-auto="" data-custo-ajuste={dif}><Zap aria-hidden="true" />Desconta {dif} PE da Energia ao Confirmar</span>
            : <span className="x-custo-jogo" data-custo-ajuste="0">Sem Devolução de PE</span>}
          {bloqueios.map((t) => <span key={t} className="x-atencao" data-bloqueio><AlertTriangle aria-hidden="true" />{t}</span>)}
          <span className="x-linha">
            <button type="button" className="m-botao x-adicionar g2-primario" disabled={bloqueios.length > 0} onClick={aoConfirmar} data-confirmar-ajuste>Confirmar Ajuste</button>
            <button type="button" className="m-botao" onClick={() => setValor(atual)} data-voltar-ajuste>Voltar</button>
          </span>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   A PREPARAÇÃO COMUM (Catálogo, primeira entrega, 2026-10-15)
   ============================================================
   Concentrar Aura, Conhecimento Aplicado e Invencível sob o Sol, com as
   MESMAS peças e classes da Preparação do piloto. O que confirmar faz vem do
   plano (`preparo.js`), refeito a cada escolha e de novo ao confirmar.
   ⚠ NO RASCUNHO, O CUSTO À MÃO É SÓ TEXTO. O Descontar abre o painel de
   Energia de verdade, e pagar antes de confirmar e depois cancelar quebraria
   a sessão intacta. O Descontar aparece no resultado e no detalhe, depois.
   ============================================================ */

/* O `m` do rascunho: a sessão com os valores escolhidos por cima, e o
   `estadoMuda` escrevendo no rascunho. Os controles de hoje servem sem mudar. */
const mDoRascunho = (m, valores, aoMudar) => ({
  ...m,
  sessao: { ...m.sessao, combate: { ...(m.sessao.combate ?? {}), ...valores } },
  estadoMuda: (e, v) => aoMudar(e, v),
});
const limiteDe = (e) => (e.maxSelecionados != null ? inteiro(e.maxSelecionados) : null);
const RotuloEscolhas = ({ e }) => <>Escolhas{limiteDe(e) != null && <small> · Até {limiteDe(e)}</small>}</>;
/* "Nenhuma Escolha" bloqueia o Confirmar, mas não vira aviso enquanto o rascunho
   está vazio de saída: ainda não é um problema. Num ajuste que tira tudo, é. */
const avisosDe = (plano) => (plano.mudou ? plano.bloqueios : plano.bloqueios.filter((t) => t !== "Nenhuma Escolha"));

/** Antes de abrir a Preparação: só o custo e quem desconta. Nada clicável. */
export function ResumoDoPreparo({ o, m }) {
  const raiz = raizDo(o.grupo);
  const c = custoAntes(o, m);
  if (c?.cobra) return <span className="x-custo-jogo" data-auto="" data-custo-resumo><Zap aria-hidden="true" />{custoEmJogo(c).texto}</span>;
  /* O custo por PARTES do estudo (E3): uma linha por parte, com o teto real do motor na parte que é o valor. */
  if (o.exemplo?.custoDoEstado) {
    const partes = o.exemplo.custoDoEstado;
    const textos = partes.filter((p) => !p.substitui).map((p) => {
      const e = o.grupo.estados.find((x) => x.id === p.estado);
      if (!e) return null;
      const quanto = p.valor ? (() => { const max = inteiro(maxDe(e, m.derived)); return max > 1 ? `de 1 a ${max} PE` : "1 PE"; })() : `${inteiro(p.pe)} PE`;
      /* A habilidade que SUBSTITUI esta parte (o Espírito Incansável, no lugar do Espírito de Luta) vai na mesma linha. */
      const versao = partes.find((x) => x.substitui === p.estado);
      return `Desconte ${quanto} da Energia${p.rotulo ? ` ${p.rotulo}` : ""}${versao ? `, ou ${inteiro(versao.pe)} PE com ${NOME_DO_FILHO[versao.estado] ?? versao.rotulo ?? versao.estado}` : ""}`;
    }).filter(Boolean);
    return textos.map((t) => <span key={t} className="x-custo-jogo" data-custo-resumo><Hand aria-hidden="true" />{t}</span>);
  }
  if (o.exemplo?.custoDoValor && raiz.tipo === "faixa") {
    const max = inteiro(maxDe(raiz, m.derived));
    return <span className="x-custo-jogo" data-custo-resumo><Hand aria-hidden="true" />{max > 1 ? `Desconte de 1 a ${max} PE da Energia` : "Desconte 1 PE da Energia"}</span>;
  }
  if (c) return <span className="x-custo-jogo" data-custo-resumo><Hand aria-hidden="true" />{custoEmJogo(c).texto}</span>;
  return <span className="x-mesa" data-custo-resumo data-sem-custo="">Sem Custo Registrado</span>;
}

/** Quem desconta o quê. A ficha: o que a simulação cobrou e o "por Rodada". À mão: só texto. No ajuste, o adicional desta operação e o total do efeito, separados. */
function CustoDoPlano({ plano, ajuste = false }) {
  const c = plano.custo;
  const out = [];
  if (c.ficha > 0) out.push(<span key="agora" className="x-custo-jogo" data-auto="" data-custo-preparo={c.ficha}><Zap aria-hidden="true" />Desconta {c.ficha} PE da Energia ao Confirmar</span>);
  if (c.rodada) out.push(<span key="rodada" className="x-custo-jogo" data-auto="" data-custo-rodada=""><Zap aria-hidden="true" />{custoEmJogo(c.rodada).texto}</span>);
  /* A Sustentação: o custo por rodada de cada Feitiço que entra, à mão (a política de pagar a manutenção é da mesa). */
  for (const x of c.sustentacao ?? []) {
    if (x.pe) out.push(<span key={`sust-${x.estado}`} className="x-custo-jogo" data-custo-sustentacao={x.pe}><Hand aria-hidden="true" />{c.sustentacao.length > 1 ? `${x.nome}: ` : ""}{custoEmJogo({ texto: `${x.pe} PE por Rodada`, cobra: false }).texto}</span>);
  }
  if (c.total != null) {
    if (c.manual > 0) out.push(<span key="mao" className="x-custo-jogo" data-custo-preparo={c.manual} data-a-mao=""><Hand aria-hidden="true" />Desconte {c.manual} PE da Energia</span>);
    else if (ajuste && c.totalAntes != null && c.total < c.totalAntes) out.push(<span key="sem" className="x-custo-jogo" data-custo-preparo="0"><Hand aria-hidden="true" />Sem Devolução de PE</span>);
    if (ajuste) out.push(<span key="total" className="x-custo" data-custo-total={c.total}>Total do Efeito: {c.total} PE</span>);
  } else if (!c.automatico && !c.ficha && !(c.sustentacao ?? []).some((x) => x.pe)) out.push(<span key="nada" className="x-mesa" data-sem-custo="">Sem Custo Registrado</span>);
  return out;
}

/* `reuso`: no USAR NOVAMENTE o que resta da reserva do uso anterior fica à vista, porque a reserva guarda o MAIOR entre ele e a concessão nova. */
/* SUSTENTAÇÃO: o que fica, o que sai e o que entra em cada vaga, antes de confirmar. Nada some calado. */
function TrocasDaSustentacao({ trocas }) {
  if (!trocas || (!trocas.saem.length && !trocas.entram.length && !trocas.ficam.length)) return null;
  return (
    <div className="g2-previa" data-trocas>
      {trocas.ficam.map((x) => <span key={`f${x.estado}`} className="x-mesa" data-fica={x.estado}>Fica: {x.nome} · {x.vaga}</span>)}
      {trocas.saem.map((x) => <span key={`s${x.estado}`} className="x-atencao" data-sai={x.estado}><AlertTriangle aria-hidden="true" />Sai: {x.nome} · {x.vaga}</span>)}
      {trocas.entram.map((x) => <span key={`e${x.estado}`} className="x-neutro" data-entra={x.estado}>Entra: {x.nome} · {x.vaga}</span>)}
    </div>
  );
}

function Previa({ previa, exemplo, reuso = false }) {
  return (
    <div className="g2-previa" data-previa>
      {previa.chips.length > 0 ? <GanhaPerde chips={previa.chips} /> : !previa.pv && <SemNumeros exemplo={exemplo} />}
      {previa.pv && (
        <span className="g-pv" data-pv-previa>
          <span>PV Temporário <b>{previa.pv.concede}</b></span>
          {previa.pv.registrado != null && previa.pv.registrado !== previa.pv.concede && <span className="g-suave" data-pv-registrado={previa.pv.registrado}>Registrado {previa.pv.registrado}</span>}
          {reuso && previa.pv.resta > 0 && <span className="g-suave" data-pv-resta={previa.pv.resta}>Restam {previa.pv.resta}</span>}
          <span className="g-suave">{previa.pv.texto}</span>
        </span>
      )}
    </div>
  );
}

/* Os usos que ATIVAR gasta (a Postura), lidos do contador real do motor. Nada é gasto antes de confirmar. */
function UsosDoPlano({ plano }) {
  const u = plano.usos;
  if (!u) return null;
  return <span className="x-custo" data-usos-restam={u.restam} data-usos-max={u.max}>Gasta 1 Uso ao Confirmar · Restam {u.restam} de {u.max}</span>;
}

/* Ligar, sem mais nada, não tem controle: é o próprio efeito. No Repertório (`exigeUm`) a raiz também é escolha. */
const ehLigarSimples = (c, raiz, exigeUm) => !exigeUm && c.estados.length === 1 && c.estados[0].id === raiz.id && c.estados[0].tipo === "bool";
/** Sem nada a ajustar: ligar sem mais nada, ou uma opção só (Golpe com Aura com uma aura). O filho que é uma ESCOLHA ao
 *  utilizar (o Espírito Incansável, `escolhaNoUso`) não é ajuste do efeito ativo: a escolha se faz na Preparação. */
export const semAjuste = (o) => {
  const gr = o.grupo;
  const escolha = preparoDe(o)?.escolhaNoUso;
  const filhos = gr.filhos.filter((f) => f.id !== escolha);
  return gr.controles.length === 1 && gr.controles[0].estados.length === 1 && !filhos.length
    && (gr.controles[0].estados[0].tipo === "bool"
      || (gr.controles[0].estados[0].tipo === "opcao" && (gr.controles[0].estados[0].opcoesVisiveis ?? gr.controles[0].estados[0].opcoes ?? []).length <= 1));
};
/* O nome do controle na linha: o do próprio controle quando ele tem partes (Duelando) ou é escolha de opção. */
const nomeDoControle = (c, e, gr) => {
  if (c.partes) return c.rotulo;
  if (e.tipo === "opcao" && e.label === gr.nome) return "Escolha";
  return c.estados.length === 1 ? rotuloDaFaixa(e, gr) : c.rotulo;
};

/* As escolhas do rascunho. `semRaiz`: o controle da raiz já está desenhado fora (o passo do ajuste). Os filhos só
   aparecem com o pai ligado no rascunho. `escolhaNoUso`: o filho que é escolhido ao UTILIZAR a habilidade (o Espírito
   Incansável) vira uma escolha entre as habilidades, pelos nomes delas, e nunca um interruptor de upgrade. */
function EscolhasDoRascunho({ gr, m, valores, aoMudar, exigeUm = false, semRaiz = false, escolhaNoUso = null }) {
  const raiz = raizDo(gr);
  const mm = mDoRascunho(m, valores, aoMudar);
  const controles = gr.controles.map((c) => {
    const e = c.estados[0];
    if (ehLigarSimples(c, raiz, exigeUm)) return null;
    if (semRaiz && c.estados.some((x) => x.id === raiz.id)) return null;
    if (c.estados.length === 1 && e.tipo === "faixa" && inteiro(maxDe(e, m.derived)) <= 6) {
      const rotulo = rotuloDaFaixa(e, gr);
      /* No Estímulo Muscular o teste pode ficar em zero (só o Empurrão). */
      const zero = exigeUm && e.id === raiz.id;
      const passos = Array.from({ length: inteiro(maxDe(e, m.derived)) + (zero ? 1 : 0) }, (_, i) => i + (zero ? 0 : 1));
      return (
        <div key={c.id} className="g2-preparo-linha">
          <span className="x-ctrl-nome">{rotulo}</span>
          <span className="m-seg g2-escolha" role="radiogroup" aria-label={rotulo} data-preparo-faixa={e.id}>
            {passos.map((n) => (
              <button key={n} type="button" role="radio" className="m-seg-op" aria-checked={n === inteiro(valores[e.id])} data-valor={n} onClick={() => aoMudar(e, n)}>{n}</button>
            ))}
          </span>
        </div>
      );
    }
    if (c.estados.length === 1 && e.tipo === "multi") {
      return (
        <div key={c.id} className="g2-preparo-linha g2-rascunho-multi">
          <span className="x-ctrl-nome"><RotuloEscolhas e={e} /></span>
          <Controle c={c} m={mm} limite={limiteDe(e)} />
        </div>
      );
    }
    return (
      <div key={c.id} className="g2-preparo-linha">
        <span className="x-ctrl-nome">{nomeDoControle(c, e, gr)}</span>
        <Controle c={c} m={mm} />
      </div>
    );
  });
  const filhos = gr.filhos.filter((f) => !gr.controles.some((c) => c.estados.some((x) => x.id === f.id))
    && gr.estados.some((p) => p.id === f.requerEstado && estaLigado(p, valores[p.id]))).map((f) => {
    if (f.id === escolhaNoUso) {
      const incansavel = estaLigado(f, valores[f.id]);
      const opcoes = [{ id: "base", nome: gr.nome, marcada: !incansavel, valor: false }, { id: f.id, nome: NOME_DO_FILHO[f.id] ?? f.label, marcada: incansavel, valor: true }];
      return (
        <div key={f.id} className="g2-preparo-linha" data-escolha-uso={f.id}>
          <span className="x-ctrl-nome">Escolha</span>
          <span className="m-seg g2-escolha" role="radiogroup" aria-label="Escolha" data-preparo-escolha-uso>
            {opcoes.map((x) => (
              <button key={x.id} type="button" role="radio" className="m-seg-op" aria-checked={x.marcada} data-opcao={x.id} onClick={() => aoMudar(f, x.valor)}>{x.nome}</button>
            ))}
          </span>
        </div>
      );
    }
    return (
      <div key={f.id} className="g2-preparo-linha" data-filho={f.id}>
        <span className="x-ctrl-nome">{NOME_DO_FILHO[f.id] ?? f.label}</span>
        <Controle c={{ id: f.id, rotulo: f.label, estados: [f] }} m={mm} />
      </div>
    );
  });
  return [...controles, ...filhos];
}

/**
 * A Preparação comum, no catálogo, no Reativar e no Usar Novamente (`modo`: "ativar" ou "reuso"). O rascunho mora fora
 * (`valores`, na tela do gerenciador), e sair dela o descarta. `onConfirmar`
 * devolve se a confirmação passou: só então o botão fica gasto.
 */
export function PreparoGrupo({ o, m, valores, onValores, onCancelar, onConfirmar, rotuloConfirmar = "Confirmar Ativação", modo = "ativar", encerrado = null }) {
  const gr = o.grupo;
  const raiz = raizDo(gr);
  const plano = useMemo(() => planoDoPreparo({ o, valores, m, modo, encerrado }), [o, valores, modo, encerrado, m.mesa, m.sessao, m.derived, m.combate]); // eslint-disable-line react-hooks/exhaustive-deps
  const antes = useMemo(() => derivarCom(m.ficha, m.sessao), [m.ficha, m.sessao]);
  const previa = useMemo(() => previaDoPlano(plano, m, antes), [plano, antes]); // eslint-disable-line react-hooks/exhaustive-deps
  const botoes = useRef(null);
  useEffect(() => { botoes.current?.scrollIntoView({ block: "nearest" }); }, []);
  const enviado = useRef(false);
  const confirmar = () => {
    if (enviado.current) return;
    enviado.current = true;
    if (!onConfirmar(valores)) enviado.current = false;
  };
  const aoMudar = (e, v) => onValores({ ...valores, [e.id]: saneia(e, v, m.derived, { raiz: e.id === raiz.id && !preparoDe(o)?.exigeUm }) });
  const exigeUm = !!preparoDe(o)?.exigeUm;
  const temEscolha = gr.controles.some((c) => !ehLigarSimples(c, raiz, exigeUm)) || gr.filhos.length > 0;
  return (
    <div className="k-confirmar g2-preparo" data-ativando="" data-preparo-grupo={o.chave}>
      {temEscolha && <h3 className="k-sub">Preparação</h3>}
      {temEscolha && <EscolhasDoRascunho gr={gr} m={m} valores={plano.alvo} aoMudar={aoMudar} exigeUm={exigeUm} escolhaNoUso={preparoDe(o)?.escolhaNoUso} />}
      <TrocasDaSustentacao trocas={plano.trocas} />
      <CustoDoPlano plano={plano} />
      <UsosDoPlano plano={plano} />
      <h3 className="k-sub">Ao Confirmar</h3>
      <Previa previa={previa} exemplo={o.exemplo} reuso={modo === "reuso"} />
      {avisosDe(plano).map((t) => <span key={t} className="x-atencao" data-bloqueio><AlertTriangle aria-hidden="true" />{t}</span>)}
      <span ref={botoes} className="x-linha">
        <button type="button" className="m-botao x-adicionar g2-primario" disabled={plano.bloqueios.length > 0 || !plano.mudou} onClick={confirmar} data-confirmar>{rotuloConfirmar}</button>
        <button type="button" className="m-botao" onClick={onCancelar} data-voltar-preparo>Voltar</button>
      </span>
    </div>
  );
}

/**
 * SUSTENTAÇÃO, no cartão da vaga (consolidação ampliada, 2026-10-16): Trocar abre a MESMA Preparação das vagas, com o que
 * fica e o que sai à vista, e Encerrar é o do cartão. O rascunho é local, parte das vagas de agora e fecha quando elas mudam.
 */
export function TrocarSustentado({ a, g, m }) {
  const o = g.opcoes.find((x) => x.chave === a.grupo.chave) ?? null;
  const combate = m.sessao.combate ?? {};
  const atuais = o ? Object.fromEntries(o.grupo.estados.map((e) => [e.id, combate[e.id] ?? null])) : {};
  const chaveAtual = JSON.stringify(atuais);
  const [valores, setValores] = useState(null);
  useEffect(() => { setValores(null); }, [chaveAtual]);
  if (!o) return <span className="x-mesa">Sem Ajuste na Ficha</span>;
  if (valores === null) {
    return (
      <span className="x-ctrl" data-trocar-sustentado={a.chave}>
        <button type="button" className="m-botao" onClick={() => setValores(rascunhoInicial(o.grupo, m.derived, atuais))} data-trocar-abrir><Repeat aria-hidden="true" />Trocar</button>
      </span>
    );
  }
  const onde = g.tela.compactaAberto === a.chave ? "compacta" : "completa";
  return (
    <PreparoGrupo o={o} m={m} valores={valores} rotuloConfirmar="Confirmar Troca"
      onValores={setValores}
      onCancelar={() => setValores(null)}
      onConfirmar={(v) => { const ok = g.acoes.confirmarPreparo(o, v, { onde }); if (ok) setValores(null); return ok; }} />
  );
}

/* ============================================================
   O MONTADOR DO GOLPE ESPECIAL (consolidação ampliada, 2026-10-16)
   ============================================================
   As marcas em rascunho, o custo que a FICHA calcula (`custoDoGolpeDaSessao`) e cobra ao confirmar (`pagaGolpeEspecial`, pelo
   `aplicaGolpe`), a prévia pelo derive e os bloqueios. Ver `g2/golpe.js`. O que cobra aqui é o contrato do montador, e não a
   regra geral de confirmar: o custo aparece como "A Ficha Desconta", sem Descontar à mão.
   ============================================================ */
const sinalDe = (n) => (n > 0 ? `+${n}` : `−${Math.abs(n)}`);

export function PreparoGolpe({ o, m, valores, onValores, onCancelar, onConfirmar, rotuloConfirmar = "Confirmar Golpe" }) {
  const plano = useMemo(() => planoDoGolpe({ valores, m, simula: m.simularGolpe }), [valores, m.mesa, m.sessao, m.derived, m.combate]); // eslint-disable-line react-hooks/exhaustive-deps
  const antes = useMemo(() => derivarCom(m.ficha, m.sessao), [m.ficha, m.sessao]);
  const chips = useMemo(() => previaDoGolpe(plano, m, antes), [plano, antes]); // eslint-disable-line react-hooks/exhaustive-deps
  const botoes = useRef(null);
  useEffect(() => { botoes.current?.scrollIntoView({ block: "nearest" }); }, []);
  const enviado = useRef(false);
  const confirmar = () => {
    if (enviado.current) return;
    enviado.current = true;
    if (!onConfirmar(valores)) enviado.current = false;
  };
  const marca = (id, v) => onValores({ ...valores, marcas: { ...plano.marcas, [id]: v } });
  /* As cinco propriedades sem estado de bancada não têm número na linha de dano: entram só no custo. */
  const semNumero = plano.propriedades.filter((p) => !p.estado && p.vezes > 0).map((p) => p.nome);
  const fora = semNumero.length ? `${semNumero.join(", ")}: entram só no custo, e a linha de dano do motor não tem número para elas` : null;
  const c = plano.custo;
  return (
    <div className="k-confirmar g2-preparo" data-ativando="" data-preparo-golpe={o.chave}>
      <h3 className="k-sub">Preparação</h3>
      <div className="g2-preparo-linha g2-rascunho-multi" data-golpe-propriedades>
        <span className="x-ctrl-nome">Propriedades</span>
        <span className="m-seg" role="group" aria-label="Propriedades do Golpe">
          {plano.propriedades.filter((p) => !p.max).map((p) => (
            <button key={p.id} type="button" className="m-seg-op" aria-pressed={p.vezes > 0} data-golpe={p.id} onClick={() => marca(p.id, p.vezes ? 0 : 1)}>{p.nome} {sinalDe(p.unidade)}</button>
          ))}
        </span>
      </div>
      {plano.propriedades.filter((p) => p.max).map((p) => (
        <div key={p.id} className="g2-preparo-linha" data-golpe-contagem={p.id}>
          <span className="x-ctrl-nome">{p.nome} {sinalDe(p.unidade)}</span>
          <span className="m-passos">
            <button type="button" className="m-passo" aria-label={`${p.nome} menos 1`} disabled={p.vezes <= 0} onClick={() => marca(p.id, p.vezes - 1)}><Minus aria-hidden="true" /></button>
            <span className="m-passos-valor" aria-live="polite" data-valor={p.vezes}>{p.vezes ? (p.niveis?.[p.vezes - 1] ?? p.vezes) : 0}<small>/{p.max}</small></span>
            <button type="button" className="m-passo" aria-label={`${p.nome} mais 1`} disabled={p.vezes >= p.max} onClick={() => marca(p.id, p.vezes + 1)}><Plus aria-hidden="true" /></button>
          </span>
        </div>
      ))}
      {plano.auto && (
        <div className="g2-preparo-linha" data-golpe-autossuficiente>
          <span className="x-ctrl-nome">Autossuficiente</span>
          <span className="m-seg g2-escolha" role="radiogroup" aria-label="Autossuficiente">
            <button type="button" role="radio" className="m-seg-op" aria-checked={!plano.seis} data-valor="3" onClick={() => onValores({ ...valores, marcas: plano.marcas, seis: false })}>3 PE</button>
            <button type="button" role="radio" className="m-seg-op" aria-checked={plano.seis} data-valor="6" disabled={plano.seisUsado} title={plano.seisUsado ? "Usado Nesta Cena" : undefined} onClick={() => onValores({ ...valores, marcas: plano.marcas, seis: true })}>6 PE</button>
          </span>
        </div>
      )}
      {c.montado && (
        <>
          <span className="x-custo-jogo" data-auto="" data-custo-golpe={c.aPagar}><Zap aria-hidden="true" />A Ficha Desconta {c.aPagar} PE{plano.sacrificio ? " e 15 de Dano" : ""}</span>
          <span className="x-custo" data-golpe-partes>
            {/* Cada parte é inteira ("Atroz +1" não se parte), e o resumo quebra linha ENTRE as partes: o texto continua o mesmo de antes. */}
            {[...c.partes.map((p) => `${p.nome}${p.vezes > 1 ? ` ×${p.vezes}` : ""} ${sinalDe(p.valor)}`), ...(c.soma !== c.total ? [`Mínimo ${c.total}`] : []), ...(c.abatido ? [`Autossuficiente −${c.abatido}`] : [])]
              .map((t, i) => <React.Fragment key={`${i}-${t}`}>{i > 0 && " · "}<span className="g2-parte">{t}</span></React.Fragment>)}
          </span>
        </>
      )}
      <h3 className="k-sub">Ao Confirmar</h3>
      <div className="g2-previa" data-previa>
        {chips.length > 0 && <GanhaPerde chips={chips} />}
        {fora ? <SemNumeros fora={fora} /> : chips.length === 0 && <SemNumeros exemplo={o.exemplo} />}
      </div>
      {plano.bloqueios.filter((t) => plano.mudou || t !== "Nenhuma Propriedade").map((t) => <span key={t} className="x-atencao" data-bloqueio><AlertTriangle aria-hidden="true" />{t}</span>)}
      <span ref={botoes} className="x-linha">
        <button type="button" className="m-botao x-adicionar g2-primario" disabled={plano.bloqueios.length > 0 || !plano.mudou} onClick={confirmar} data-confirmar>{rotuloConfirmar}</button>
        <button type="button" className="m-botao" onClick={onCancelar} data-voltar-preparo>Voltar</button>
      </span>
    </div>
  );
}

/** O Golpe Especial ativo: montar OUTRO golpe é um golpe novo, de custo inteiro, pela mesma Preparação das marcas de agora. */
export function MontarOutroGolpe({ a, g, m }) {
  const combate = m.sessao.combate ?? {};
  const chaveAtual = JSON.stringify(a.grupo.estados.map((e) => combate[e.id] ?? null)) + JSON.stringify(m.sessao.golpeEspecial ?? {});
  const [valores, setValores] = useState(null);
  useEffect(() => { setValores(null); }, [chaveAtual]);
  if (valores === null) {
    return (
      <span className="x-ctrl" data-montar-outro={a.chave}>
        <button type="button" className="m-botao" onClick={() => setValores(rascunhoDoGolpe(m))} data-montar-outro-abrir><Repeat aria-hidden="true" />Montar Outro Golpe</button>
      </span>
    );
  }
  const onde = g.tela.compactaAberto === a.chave ? "compacta" : "completa";
  return (
    <PreparoGolpe o={a} m={m} valores={valores} rotuloConfirmar="Confirmar Golpe"
      onValores={setValores}
      onCancelar={() => setValores(null)}
      onConfirmar={(v) => { const ok = g.acoes.confirmarGolpe(a, v, { onde }); if (ok) setValores(null); return ok; }} />
  );
}

/**
 * USAR NOVAMENTE (autor, 2026-10-16): não existe aumentar o uso atual. Existe um uso novo, com o valor que o jogador
 * escolher, e a Preparação é a mesma da ativação, com o custo INTEIRO (9 PE de novo custam 9) e o pagamento à mão.
 * Cancelar não toca o uso anterior nem a reserva de PV. O rascunho é local e começa no valor de agora (pode ser o mesmo).
 */
export function UsarNovamente({ a, g, m }) {
  const gr = a.grupo;
  const combate = m.sessao.combate ?? {};
  const atuais = Object.fromEntries(gr.estados.map((e) => [e.id, combate[e.id]]));
  const chaveAtual = JSON.stringify(atuais);
  const [valores, setValores] = useState(null);
  /* O uso mudou (confirmou aqui ou na outra apresentação): o rascunho fecha, e o próximo recomeça do valor de agora. */
  useEffect(() => { setValores(null); }, [chaveAtual]);
  if (valores === null) {
    return (
      <span className="x-ctrl" data-usar-novamente={a.chave}>
        <button type="button" className="m-botao" onClick={() => setValores(rascunhoInicial(gr, m.derived, atuais))} data-usar-novamente-abrir><Repeat aria-hidden="true" />Usar Novamente</button>
      </span>
    );
  }
  return (
    <PreparoGrupo o={a} m={m} valores={valores} modo="reuso" rotuloConfirmar="Confirmar Novo Uso"
      onValores={setValores}
      onCancelar={() => setValores(null)}
      onConfirmar={(v) => { const ok = g.acoes.confirmarNovoUso(a, v); if (ok) setValores(null); return ok; }} />
  );
}

/**
 * O ajuste do cartão ativo, em rascunho: nada muda até Confirmar Ajuste.
 * Faixa em passos (como o piloto), escolhas com o limite. Parado, o custo à
 * mão mostra o TOTAL do efeito e o Descontar (o efeito já foi confirmado).
 */
export function AjusteGrupo({ a, g, m }) {
  const gr = a.grupo;
  const raiz = raizDo(gr);
  const combate = m.sessao.combate ?? {};
  const atuais = Object.fromEntries(gr.estados.map((e) => [e.id, combate[e.id]]));
  const chaveAtual = JSON.stringify(atuais);
  const [valores, setValores] = useState(() => rascunhoInicial(gr, m.derived, atuais));
  const enviado = useRef(false);
  /* A sessão mudou (confirmou aqui ou na outra apresentação): o rascunho recomeça dela. */
  useEffect(() => { setValores(rascunhoInicial(gr, m.derived, atuais)); enviado.current = false; }, [chaveAtual]); // eslint-disable-line react-hooks/exhaustive-deps
  const plano = useMemo(() => planoDoPreparo({ o: a, valores, m, modo: "ajuste" }), [a, valores, m.mesa, m.sessao, m.derived, m.combate]); // eslint-disable-line react-hooks/exhaustive-deps
  /* Parado, nada a comparar: os dois derives só rodam com o rascunho mudado. */
  const previa = useMemo(() => (plano.mudou ? previaDoPlano(plano, m, derivarCom(m.ficha, m.sessao)) : null), [plano]); // eslint-disable-line react-hooks/exhaustive-deps
  const pendente = useRef(null);
  useEffect(() => { if (plano.mudou) pendente.current?.scrollIntoView({ block: "nearest" }); }, [plano.mudou]);
  const aoMudar = (e, v) => setValores((x) => ({ ...x, [e.id]: saneia(e, v, m.derived, { raiz: e.id === raiz.id && !preparoDe(a)?.exigeUm }) }));
  const confirmar = () => {
    if (enviado.current) return;
    enviado.current = true;
    if (!g.acoes.confirmarAjustePreparo(a, valores)) enviado.current = false;
  };
  const exigeUm = !!preparoDe(a)?.exigeUm;
  let rotulo = null;
  let controle;
  if (raiz.tipo === "faixa") {
    rotulo = rotuloDaFaixa(raiz, gr);
    const max = inteiro(maxDe(raiz, m.derived));
    const n = inteiro(plano.alvo[raiz.id]);
    controle = (
      <span className="m-passos">
        <button type="button" className="m-passo" aria-label={`${rotulo} menos 1`} disabled={n <= (exigeUm ? 0 : 1)} onClick={() => aoMudar(raiz, n - 1)}><Minus aria-hidden="true" /></button>
        <span className="m-passos-valor" aria-live="polite" data-ajuste-valor={n}>{n}<small>/{max}</small></span>
        <button type="button" className="m-passo" aria-label={`${rotulo} mais 1`} disabled={n >= max} onClick={() => aoMudar(raiz, n + 1)}><Plus aria-hidden="true" /></button>
      </span>
    );
  } else if (raiz.tipo === "multi") {
    rotulo = <RotuloEscolhas e={raiz} />;
    controle = <Controle c={gr.controles[0]} m={mDoRascunho(m, plano.alvo, aoMudar)} limite={limiteDe(raiz)} />;
  } else if (semAjuste(a)) {
    return <span className="x-mesa">Sem Ajuste na Ficha</span>;
  }
  /* Os interruptores e a opção (Repertório, Golpe com Aura): uma linha por controle, os mesmos do rascunho do catálogo. */
  const escolhas = controle === undefined;
  return (
    <div className="x-ctrl" data-ajuste-grupo={a.chave}>
      {escolhas
        ? <EscolhasDoRascunho gr={gr} m={m} valores={plano.alvo} aoMudar={aoMudar} exigeUm={exigeUm} />
        : (
          <>
            <span className="x-ctrl-nome">{rotulo}</span>
            <span className={`x-ctrl-linha${raiz.tipo === "multi" ? " g2-rascunho-multi" : ""}`}>
              {controle}
              {!plano.mudou && plano.custo.total != null && (
                <>
                  <span className="x-custo" data-custo-total={plano.custo.total}>Total do Efeito: {plano.custo.total} PE</span>
                  <GastarNaEnergia m={m} nome={a.nome} rotulo="Descontar" />
                </>
              )}
            </span>
            {(gr.controles.length > 1 || gr.filhos.length > 0) && <EscolhasDoRascunho gr={gr} m={m} valores={plano.alvo} aoMudar={aoMudar} exigeUm={exigeUm} semRaiz />}
          </>
        )}
      {escolhas && !plano.mudou && plano.custo.total != null && (
        <span className="x-linha">
          <span className="x-custo" data-custo-total={plano.custo.total}>Total do Efeito: {plano.custo.total} PE</span>
          <GastarNaEnergia m={m} nome={a.nome} rotulo="Descontar" />
        </span>
      )}
      {plano.mudou && (
        <div ref={pendente} className="g2-ajuste" data-ajuste-pendente>
          <CustoDoPlano plano={plano} ajuste />
          {previa && <Previa previa={previa} exemplo={a.exemplo} />}
          {avisosDe(plano).map((t) => <span key={t} className="x-atencao" data-bloqueio><AlertTriangle aria-hidden="true" />{t}</span>)}
          <span className="x-linha">
            <button type="button" className="m-botao x-adicionar g2-primario" disabled={plano.bloqueios.length > 0} onClick={confirmar} data-confirmar-ajuste>Confirmar Ajuste</button>
            <button type="button" className="m-botao" onClick={() => setValores(rascunhoInicial(gr, m.derived, atuais))} data-voltar-ajuste>Voltar</button>
          </span>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   EFEITOS: A CAMADA DE DADOS (a mesma para a visão completa e a compacta)
   ============================================================
   Nenhum número é escrito aqui. O que tem valor sai do motor, sempre por
   `prepararCalculo` (recebidos.js), que é o que põe as fontes externas na
   conta com as regras de acúmulo:
     - o que um efeito ativo dá é o derive COM ele contra o derive SEM ele;
     - o que uma opção daria ao ligar é o mesmo derive, simulado;
     - o que foi cobrado é a diferença de PE medida depois da operação.

   GRUPO é uma habilidade com os seus parâmetros:
     1. o filho (`requerEstado`) vai com o pai ("Espírito de Luta · 2 PE");
     2. "X · Parte" vai com o estado "X" (Postura e Postura · Segunda);
     3. o dono no Repertório: a Habilidade, a Aptidão com o mesmo nome
        quando o motor só declara a categoria, e o Feitiço do interruptor
        `feiticoLigado_<id>`;
     4. as vagas de Sustentação formam um grupo só, e cada vaga ocupada
        aparece nos ativos como o Feitiço que ela mantém.
   ============================================================ */
import {
  comAddons, estaLigado, padraoDe, compararSaldo, correspondeFiltroHabilidade, fichaDaCondicao, donoDoEstado, GRUPOS, Sessao,
} from "./ponte";
import { donoNoRepertorio } from "./repertorio";
import { semAcento } from "./util";
import { PROPRIEDADES_GOLPE, marcasDoGolpe } from "../../afty-golpe-especial";
import { exemploDe, exemploDeEstado, RECEBIDOS, PV_TEMP, FONTE_TERRA_INVENCIVEL } from "./exemplos";
import { prepararCalculo, ehRegistro, disputasPorFonte, TIPOS_FONTE } from "./recebidos";

const GRUPO_IDS = new Set(GRUPOS.map((g) => g.id));
const ORIGEM_CURTA = {
  origem: "Origem", especializacao: "Habilidade", passivo: "Passiva", estilo: "Estilo", talento: "Talento",
  geral: "Habilidade Geral", aptidao: "Aptidão", altoNivel: "Nível Lendário",
};
export const COMO = {
  ligar: "Ligar e Desligar",
  modo: "Postura ou Modo",
  intensidade: "Intensidade ou Acúmulo",
  escolhas: "Escolhas",
  usar: "Usar",
  registrar: "Uso Instantâneo",
  sempre: "Sempre Valendo",
  consulta: "Sem Controle na Ficha",
};
export const ORDEM_COMO = ["ligar", "modo", "intensidade", "escolhas", "usar", "registrar", "sempre", "consulta"];

export const rotuloOpcao = (l) => String(l ?? "").replace(/^Postura d[oae]s? /, "");
/* O nome da HABILIDADE de um estado filho, e não o custo no rótulo do motor ("Espírito de Luta · 2 PE"). O PE é
   informação de custo, e a escolha entre Espírito de Luta e Espírito Incansável é feita ao UTILIZAR (autor, 2026-10-16). */
export const NOME_DO_FILHO = { espiritoIncansavel: "Espírito Incansável" };
const idCurto = (chave) => String(chave ?? "").split(":").pop();
export const exemploDoItem = (item) => (item ? exemploDe(item.id) ?? exemploDe(idCurto(item.chave)) : null);
/* O texto do estudo de um grupo: o da habilidade dona, ou, sem dona (o estado de
   um encantamento da bancada), o do estado raiz. */
export const exemploDoGrupo = (g) => exemploDoItem(g.item) ?? (g.item ? null : exemploDeEstado(g.raiz.id));
const ehVagaSustentacao = (e) => /^sustentacaoFeitico\d+$/.test(e?.id ?? "");
const derivarCom = (ficha, sessao) => prepararCalculo(ficha, sessao).derived;

export function origemDoItem(item) {
  if (!item) return null;
  if (item.tipo === "feitico") return { tipo: "feitico", rotulo: "Feitiço", curta: "Feitiço", detalhe: (item.marcas ?? []).join(" · ") };
  const tipo = item.grupo === "aptidao" ? "aptidao" : "habilidade";
  const detalhe = [item.sub?.label, ...(item.tags ?? []).map((t) => t.label).filter((l) => l !== item.sub?.label)].filter(Boolean).join(" · ");
  const rotulo = ORIGEM_CURTA[item.grupo] ?? "Habilidade";
  return { tipo, rotulo, detalhe, curta: item.grupo === "especializacao" ? item.sub?.label ?? rotulo : rotulo };
}

/* ---------------- o que muda: a comparação do motor, completa ---------------- */
/* `compararSaldo` olha o total e os dados da primeira linha de ataque. Canalizar
   em Golpe e afins somam um GRUPO de dados que ela não vê, e a Margem de Crítico
   também fica de fora. As duas leituras vêm do mesmo derive. */
function gruposDiferentes(com, sem, sinal) {
  const a = com.dano?.entradas?.[0]?.gruposDano ?? [];
  const nomesB = new Set((sem.dano?.entradas?.[0]?.gruposDano ?? []).map((x) => x.nome));
  return a.filter((x) => x.nome && !nomesB.has(x.nome)).map((x) => ({
    chave: `grupo:${x.nome}`, rotulo: x.nome, valor: sinal,
    texto: `${sinal > 0 ? "+" : "−"}${x.dados}d${x.faces}${x.fixo ? `+${x.fixo}` : ""}`,
  }));
}
function margemDiferente(com, sem) {
  const a = com.dano?.entradas?.[0]?.margemCritico;
  const b = sem.dano?.entradas?.[0]?.margemCritico;
  if (a == null || b == null || a === b) return [];
  const d = a - b;
  return [{ chave: "margemCritico", rotulo: "Margem de Crítico", valor: -d, texto: `${d > 0 ? "+" : "−"}${Math.abs(d)}` }];
}
/* E3 (2026-10-16): dois resultados que o motor JÁ calcula e o comparador do motor não olha.
   - os testes nomeados (Concentração, Fintar, Provocar e Teste de Morte), no total `executar` que o derive põe em
     `testes.manobras`. A Mente Plácida entra por aqui, com a escada do motor (+3 com 1 PE e +5 com 2 PE). As quatro
     Manobras ficam de fora: o total delas já muda com a perícia e o ataque, e entraria dobrado;
   - a distância do Empurrão (`distanciaEmpurrao`), somada dos detalhes de efeito que o motor aplicou.
   Nada é calculado aqui: é a diferença de dois derives, como o resto. */
const TESTES_NOMEADOS = new Set(["concentracao", "fintar", "provocar", "morte"]);
const fmtM = (n) => String(Math.round(n * 10) / 10).replace(".", ",");
function testesNomeadosDiferentes(com, sem) {
  const bs = new Map((sem.testes?.manobras ?? []).map((m) => [m.id, m]));
  return (com.testes?.manobras ?? []).filter((m) => TESTES_NOMEADOS.has(m.id)).flatMap((m) => {
    const d = (m.executar ?? 0) - (bs.get(m.id)?.executar ?? 0);
    return d ? [{ chave: `teste:${m.id}`, rotulo: m.nome ?? m.id, valor: d, texto: `${d > 0 ? "+" : "−"}${Math.abs(d)}` }] : [];
  });
}
const empurrao = (d) => (d.efeitos?.detalhes ?? []).filter((x) => x.canal === "distanciaEmpurrao" && !x.suplantado).reduce((s, x) => s + (Number(x.valor) || 0), 0);
function empurraoDiferente(com, sem) {
  const d = empurrao(com) - empurrao(sem);
  return d ? [{ chave: "distanciaEmpurrao", rotulo: "Empurrão", valor: d, texto: `${d > 0 ? "+" : "−"}${fmtM(Math.abs(d))} m` }] : [];
}
export const compararTudo = (com, sem) => [...compararSaldo(com, sem), ...margemDiferente(com, sem), ...gruposDiferentes(com, sem, 1), ...gruposDiferentes(sem, com, -1),
  ...testesNomeadosDiferentes(com, sem), ...empurraoDiferente(com, sem)];
export const COMPARADOS = "Ataque Básico (Acerto, Dano, Dados, Margem de Crítico e grupos de dados), Testes de Resistência, Perícias, Defesa, RD, PV Temporário, Movimento, Iniciativa, Atenção, CD, PV e PE Máximos, os testes nomeados (Concentração, Fintar, Provocar e Teste de Morte) e a distância do Empurrão";

/* A consequência principal de uma linha: a primeira nesta ordem, e o resto no detalhe. */
const PRIORIDADE = ["defesa", "acerto", "dano", "dados", "margemCritico", "rdGeral", "rdFisico", "rdEspecifico", "pvTemporario", "movimento", "iniciativa", "atencao", "cd", "hp", "pe"];
const peso = (c) => {
  const i = PRIORIDADE.indexOf(c.chave);
  if (i >= 0) return i;
  if (c.chave.startsWith("grupo:")) return 3.5;
  if (c.chave.startsWith("tr:")) return 20;
  if (c.chave.startsWith("pericia:")) return 21;
  return 30;
};
export const ordenarConsequencias = (chips) => [...chips].sort((a, b) => peso(a) - peso(b));

const maxDe = (e, derived) => (typeof e.max === "function" ? e.max(derived) : e.max);
const custoDe = (e, v) => (typeof e.custoPE === "function" ? e.custoPE(v) : e.custoPE);

/* ---------------- grupos ---------------- */
export function montarGrupos(pacote) {
  const { estados, controles, rep } = pacote;
  const porId = new Map(estados.map((e) => [e.id, e]));
  const porLabel = new Map(estados.map((e) => [e.label, e]));
  const aptPorNome = new Map(rep.todas.filter((i) => i.grupo === "aptidao").map((i) => [i.nome, i]));
  const raizDe = (e) => { let x = e; for (let i = 0; i < 8 && x.requerEstado && porId.has(x.requerEstado); i++) x = porId.get(x.requerEstado); return x; };
  const memo = new Map();
  const donoDe = (e0) => {
    if (memo.has(e0.id)) return memo.get(e0.id);
    const e = raizDe(e0);
    let r;
    if (ehVagaSustentacao(e)) r = { chave: "estado:sustentacao", item: null, raiz: e, sustentacao: true };
    else {
      const i = e.label.indexOf(" · ");
      const pai = i > 0 ? porLabel.get(e.label.slice(0, i)) : null;
      if (pai && pai !== e) r = donoDe(pai);
      else {
        const item = (e.feiticoId ? rep.porChave.get(`feitico:${e.feiticoId}`) : null) ?? donoNoRepertorio(e, rep) ?? aptPorNome.get(e.label) ?? null;
        r = item ? { chave: item.chave, item, raiz: e } : { chave: `estado:${e.id}`, item: null, raiz: e };
      }
    }
    memo.set(e0.id, r);
    return r;
  };
  const grupos = new Map();
  for (const e of estados) {
    const d = donoDe(e);
    if (!grupos.has(d.chave)) grupos.set(d.chave, { chave: d.chave, item: d.item, raiz: d.raiz, sustentacao: !!d.sustentacao, estados: [], controles: [] });
    grupos.get(d.chave).estados.push(e);
  }
  for (const c of controles) grupos.get(donoDe(c.estados[0]).chave)?.controles.push(c);
  const out = [];
  for (const g of grupos.values()) {
    if (!g.controles.length) continue;
    const e0 = g.controles[0].estados[0];
    g.nome = g.sustentacao ? "Sustentação" : g.item?.nome ?? g.raiz.label;
    g.filhos = g.estados.filter((e) => e.requerEstado);
    g.recebido = RECEBIDOS[g.raiz.id] ?? null;
    g.origem = g.sustentacao ? { tipo: "feitico", rotulo: "Feitiço", curta: "Feitiço", detalhe: "Vagas de Sustentação" }
      : g.item ? origemDoItem(g.item)
        : g.recebido ? { tipo: "recebido", rotulo: "Recebido", curta: "Recebido", detalhe: donoDoEstado(g.raiz)?.label ?? "" }
          : { tipo: "outros", rotulo: donoDoEstado(g.raiz)?.label ?? "Outros", curta: donoDoEstado(g.raiz)?.label ?? "Outros", detalhe: "" };
    g.como = g.controles[0].partes ? "ligar" : ({ bool: "ligar", opcao: "modo", faixa: "intensidade", multi: "escolhas" })[e0.tipo] ?? "ligar";
    g.porId = porId;
    out.push(g);
  }
  return out;
}

/* O GOLPE ESPECIAL (consolidação ampliada, 2026-10-16, corrigido na devolutiva da E6). As onze propriedades moram em DUAS casas do motor: seis
   são estados de bancada (`sessao.combate`) e cinco são marcas próprias (`sessao.golpeEspecial`: Amplo, Impactante, Sanguinário, Lento e
   Sacrifício). Um golpe só com marcas próprias está montado e pago, mas nenhum estado do grupo está ligado. O reconhecimento é pelo montador
   (`marcasDoGolpe`, módulo folha do motor), sem estado falso nem marca escondida. */
export const CHAVE_GOLPE = "especializacao:cmb_golpe_especial";
export const golpeMarcado = (sessao) => !!sessao && Object.values(marcasDoGolpe(sessao)).some((n) => n > 0);
/** As propriedades do Golpe Especial que estão marcadas, nas duas casas: [{ id, nome, vezes, texto }]. Sem marca nenhuma, vazio. */
export function propriedadesDoGolpe(sessao) {
  const marcas = marcasDoGolpe(sessao);
  return PROPRIEDADES_GOLPE.filter((p) => marcas[p.id] > 0).map((p) => ({
    id: p.id, nome: p.nome, vezes: marcas[p.id],
    texto: p.max ? `${p.nome} ${p.niveis?.[marcas[p.id] - 1] ?? marcas[p.id]}` : p.nome,
  }));
}
/** O grupo está ligado? `sessao` só importa ao Golpe Especial, cujas marcas próprias não são estados. */
export const grupoLigado = (g, combate, sessao = null) => g.estados.some((e) => estaLigado(e, combate?.[e.id])) || (g.chave === CHAVE_GOLPE && golpeMarcado(sessao));

/** O que está valendo em cada controle do grupo: [{ rotulo, texto }]. */
export function valoresDoGrupo(g, combate) {
  const out = [];
  const depois = (l) => (l.includes(" · ") ? l.slice(l.indexOf(" · ") + 3) : l);
  const antes = (l) => (l.includes(" · ") ? l.slice(0, l.indexOf(" · ")) : l);
  const nomeBool = (l) => (l === g.nome ? "Ligado" : antes(l) === g.nome ? depois(l) : antes(l));
  g.controles.forEach((c, i) => {
    if (!c.estados.some((e) => estaLigado(e, combate?.[e.id]))) return;
    if (c.partes) {
      const texto = c.estados.map((e, j) => (estaLigado(e, combate?.[e.id]) ? c.partes[j] : null)).filter(Boolean).join(", ");
      const rotulo = c.rotulo && c.rotulo !== g.nome && !texto.includes(c.rotulo) ? antes(c.rotulo) : null;
      out.push({ rotulo: rotulo === texto ? null : rotulo, texto });
      return;
    }
    const e = c.estados[0];
    const v = combate?.[e.id];
    const ops = e.opcoesVisiveis ?? e.opcoes ?? [];
    if (e.tipo === "bool") { out.push({ rotulo: null, texto: nomeBool(e.label) }); return; }
    const texto = e.tipo === "faixa" ? String(Math.trunc(Number(v) || 0))
      : e.tipo === "multi" ? ops.filter((o) => (v ?? []).includes(o.id)).map((o) => rotuloOpcao(o.label)).join(", ")
        : rotuloOpcao(ops.find((o) => o.id === v)?.label);
    const rotulo = i === 0 && (e.label === g.nome || !e.label.includes(" · ")) ? null : depois(e.label);
    out.push({ rotulo, texto });
  });
  for (const f of g.filhos) {
    const v = combate?.[f.id];
    if (!estaLigado(f, v)) continue;
    const ops = f.opcoesVisiveis ?? f.opcoes ?? [];
    /* O grau do aliado vai junto do nome dele ("Protetor Veterano"), e não repete. */
    const pai = out.find((x) => x.texto?.split(", ").includes(depois(f.label)));
    if (f.tipo === "opcao" && pai) { pai.texto = pai.texto.split(", ").map((t) => (t === depois(f.label) ? `${t} ${rotuloOpcao(ops.find((o) => o.id === v)?.label)}` : t)).join(", "); continue; }
    /* "Espírito de Luta · 2 PE" é o Espírito Incansável: pelo nome da habilidade, e não pelo custo no rótulo. */
    if (f.tipo === "bool") out.push({ rotulo: null, texto: NOME_DO_FILHO[f.id] ?? depois(f.label) });
    else if (f.tipo === "opcao") out.push({ rotulo: depois(f.label), texto: rotuloOpcao(ops.find((o) => o.id === v)?.label) });
    else if (f.tipo === "faixa") out.push({ rotulo: depois(f.label), texto: String(Math.trunc(Number(v) || 0)) });
    else if (f.tipo === "multi") out.push({ rotulo: depois(f.label), texto: ops.filter((o) => (v ?? []).includes(o.id)).map((o) => rotuloOpcao(o.label)).join(", ") });
  }
  return out;
}

/* ---------------- opções: a ficha inteira, encontrável ---------------- */
export function montarOpcoes(pacote, grupos) {
  const porChave = new Map(grupos.map((g) => [g.chave, g]));
  const out = [];
  const indice = (o, extraNome = [], extraTexto = []) => ({
    ...o,
    texto: o.item?.texto ?? o.recebido ?? o.grupo?.raiz?.title ?? "",
    opcoes: o.item?.opcoes ?? [],
    buscaNome: semAcento([o.nome, ...extraNome].join(" \n ")),
    busca: semAcento([o.nome, ...extraNome, o.item?.texto, o.exemplo?.texto, o.recebido, ...(o.item?.opcoes ?? []).map((x) => `${x.nome} ${x.descricao ?? ""}`), ...extraTexto].filter(Boolean).join(" \n ")),
  });
  for (const g of grupos) {
    const nomesCtrl = g.estados.map((e) => e.label).filter((l) => l !== g.nome);
    const ops = g.estados.flatMap((e) => (e.opcoesVisiveis ?? e.opcoes ?? []).map((o) => o.label));
    const ex = exemploDoGrupo(g);
    const custoConj = g.item?.tipo === "feitico" ? Math.max(0, Math.trunc(Number(g.item.ref?.custoPE) || 0)) : null;
    out.push(indice({ chave: g.chave, nome: g.nome, item: g.item, grupo: g, origem: g.origem, como: g.como, exemplo: ex, recebido: g.recebido, custoConjuracao: custoConj }, nomesCtrl, [...ops, g.raiz.title]));
  }
  for (const i of pacote.rep.todas) {
    if (porChave.has(i.chave)) continue;
    if (String(i.id ?? "").startsWith("rec_")) continue; // Feitiço recebido gerado para a conta
    const ehFeitico = i.tipo === "feitico";
    if (!ehFeitico && !GRUPO_IDS.has(i.grupo)) continue;
    const ex = exemploDoItem(i);
    const passivo = ehFeitico && i.ref?.tipo === "passivo";
    /* Sempre Valendo só quando o DADO diz: o Feitiço Passivo (`grupo: "passivo"`, do tipo `passivo` do catálogo
       de Feitiços) é um benefício permanente, sem ação. O resto sem controle continua "Sem Controle" até um
       texto do estudo dizer `como: "sempre"`: número permanente no derive não prova passividade. */
    const feiticoPassivo = i.grupo === "passivo";
    const como = ehFeitico ? (passivo ? "sempre" : "usar") : feiticoPassivo ? "sempre" : ex?.como ?? "consulta";
    out.push(indice({ chave: i.chave, nome: i.nome, item: i, grupo: null, origem: origemDoItem(i), como, exemplo: ex, custoUsar: ehFeitico && !passivo ? Math.max(0, Math.trunc(Number(i.ref?.custoPE) || 0)) : null }));
  }
  return out;
}

/* ---------------- a finalidade ---------------- */
export const PARA = [
  { id: "acerto", rotulo: "Acerto", calc: (c) => c.chave === "acerto", texto: "acerto" },
  { id: "dano", rotulo: "Dano", calc: (c) => c.chave === "dano" || c.chave === "dados" || c.chave.startsWith("grupo:"), texto: "dano" },
  { id: "defesa", rotulo: "Defesa", calc: (c) => c.chave === "defesa", texto: "defesa" },
  { id: "resistencia", rotulo: "Resistências", calc: (c) => c.chave.startsWith("tr:") },
  { id: "rd", rotulo: "Redução de Dano", calc: (c) => /^rd/.test(c.chave) },
  { id: "pvtemp", rotulo: "PV Temporário", calc: (c) => c.chave === "pvTemporario" },
  { id: "movimento", rotulo: "Movimento", calc: (c) => c.chave === "movimento" },
  { id: "pericia", rotulo: "Perícias", calc: (c) => c.chave.startsWith("pericia:") },
  { id: "furtividade", rotulo: "Furtividade", calc: (c) => c.chave === "pericia:furtividade", texto: "furtividade" },
  { id: "atencao", rotulo: "Atenção", calc: (c) => c.chave === "atencao", texto: "atencao" },
];

function casosDe(g, combate, derived) {
  const c = g.controles[0];
  if (c.partes) return c.estados.filter((e) => !estaLigado(e, combate?.[e.id])).map((e, i) => ({ rotulo: c.partes[c.estados.indexOf(e)] ?? String(i), patch: { [e.id]: e.tipo === "faixa" ? Math.max(1, e.min ?? 0) : true } }));
  const e = c.estados[0];
  const v = combate?.[e.id];
  const ops = e.opcoesVisiveis ?? e.opcoes ?? [];
  if (e.tipo === "bool") return v ? [] : [{ rotulo: null, patch: { [e.id]: true } }];
  if (e.tipo === "faixa") {
    const max = maxDe(e, derived) ?? 99;
    const n = Math.trunc(Number(v) || (e.min ?? 0));
    return n < max ? [{ rotulo: n > (e.min ?? 0) ? `Com ${n + 1}` : null, patch: { [e.id]: n + 1 } }] : [];
  }
  if (e.tipo === "multi") return ops.filter((o) => !(v ?? []).includes(o.id)).map((o) => ({ rotulo: `${(v ?? []).length ? "Somar " : ""}${rotuloOpcao(o.label)}`, patch: { [e.id]: [...(v ?? []), o.id] } }));
  return ops.filter((o) => o.id !== v).map((o) => ({ rotulo: `${v ? "Trocar para " : ""}${rotuloOpcao(o.label)}`, patch: { [e.id]: o.id } }));
}

/** O que cada grupo daria ao ligar, pelo derive (com os recebidos na conta). */
export function simularGrupos(ficha, sessao, grupos) {
  const combate = { ...(sessao.combate ?? {}), ativo: true };
  const base = { ...sessao, combate };
  const antes = derivarCom(ficha, base);
  const out = new Map();
  for (const g of grupos) {
    const casos = casosDe(g, combate, antes);
    out.set(g.chave, casos.map((k) => ({ rotulo: k.rotulo, chips: compararTudo(derivarCom(ficha, { ...base, combate: { ...combate, ...k.patch } }), antes) })));
  }
  return out;
}

export function finalidadeDe(o, para, simulacao) {
  const casos = simulacao?.get(o.chave) ?? [];
  const achados = casos.filter((k) => k.chips.some((c) => para.calc(c) && (c.valor ?? 0) > 0));
  if (achados.length) return { prova: "calculo", casos: achados };
  if (para.texto && o.item && correspondeFiltroHabilidade({ id: o.item.id, nome: o.item.nome, texto: o.item.texto, opcoes: o.item.opcoes }, para.texto, "")) return { prova: "regra", casos: [] };
  return null;
}

/* ---------------- o que dá para verificar antes de usar ---------------- */
export function verificacoes(o, m) {
  const ok = [];
  const nao = [];
  const combate = m.sessao.combate ?? {};
  const disponivel = m.sessao.peAtual + Sessao.peTempTotal(m.sessao);
  if (o.como === "usar" && o.custoUsar != null && disponivel < o.custoUsar) nao.push(`Faltam ${o.custoUsar - disponivel} PE`);
  if (o.grupo) {
    if (!m.combate) nao.push("Pede Em Combate");
    for (const e of o.grupo.estados) {
      if (e.id === "invencivelSobOSol" && !combate.invencivelSobOSol && disponivel < 4) nao.push("Faltam PE");
      if (e.umaVezPorRodada && Sessao.estadoUsadoNestaRodada(m.sessao, e.id)) nao.push("Já Usado Nesta Rodada");
      /* A TRAVA DO FEITIÇO PERMUTATIVO (autor, 2026-10-02): "o Feitiço não pode ser usado". Desligado, ela impede de ligar,
         como na aba Buffs da aplicação principal (`bloqueio(derived, ligado)`). Ligado, vira aviso no cartão. */
      if (typeof e.bloqueio === "function" && !estaLigado(e, combate[e.id])) { const t = e.bloqueio(m.derived, false); if (t) nao.push(t); }
    }
  }
  return { ok, nao };
}

export function naMesaDe(o) {
  const ex = o.exemplo;
  return [
    ex?.quando && { rotulo: "Quando", texto: ex.quando },
    ex?.duracao && { rotulo: "Duração", texto: ex.duracao },
    ex?.usos && { rotulo: "Usos", texto: ex.usos },
  ].filter(Boolean);
}

/**
 * As partes do custo À MÃO do estudo (`custoDoEstado` em exemplos.js), com o PE de cada uma pelos valores de
 * `combate`: [{ estado, valor, pe, rotulo, substitui, ligado, gasto }]. `gasto` é o PE da parte nestes valores. Uma parte
 * `substitui` outra: ligada, a outra deixa de custar (os 2 PE do Espírito Incansável no lugar do 1 PE do Espírito de Luta). Null quando o estudo
 * não tem custo por partes.
 */
export function partesDoCusto(gr, combate, exemplo) {
  const lista = exemplo?.custoDoEstado;
  if (!lista) return null;
  const inteiro = (v) => Math.max(0, Math.trunc(Number(v) || 0));
  const partes = lista.map((p) => {
    const e = gr.estados.find((x) => x.id === p.estado);
    const ligado = !!e && estaLigado(e, combate?.[e.id]);
    return { ...p, ligado, gasto: !ligado ? 0 : p.valor ? inteiro(combate?.[e.id]) : inteiro(p.pe) };
  });
  for (const p of partes) {
    if (p.substitui && p.ligado) { const alvo = partes.find((x) => x.estado === p.substitui); if (alvo) alvo.gasto = 0; }
  }
  return partes;
}

/** O custo ANTES da ação, curto: { texto, cobra } ou null. `cobra` é da ficha. */
export function custoAntes(o, m) {
  const g = o.grupo;
  if (g?.estados.some((e) => e.id === "invencivelSobOSol")) return { texto: "4 PE por Rodada", cobra: true };
  if (o.como === "usar" && o.custoUsar) return { texto: `${o.custoUsar} PE`, cobra: true };
  if (g) {
    const e0 = g.controles[0].estados[0];
    const v = e0.tipo === "faixa" ? Math.max(1, (e0.min ?? 0) + 1) : true;
    const c = custoDe(e0, v);
    if (c != null) return { texto: `${c} PE`, cobra: false };
  }
  if (o.custoConjuracao) return { texto: `${o.custoConjuracao} PE`, cobra: false };
  if (o.exemplo?.custoCurto) return { texto: typeof o.exemplo.custoCurto === "string" ? o.exemplo.custoCurto : o.exemplo.custoCurto.padrao, cobra: false };
  return null;
}

/* ---------------- ativos ---------------- */
const ORDEM_ATIVO = { condicao: 0, recebido: 1, proprio: 2 };
const TIPO_ROTULO = Object.fromEntries(TIPOS_FONTE.map((t) => [t.id, t.rotulo]));

export function montarAtivos(m, grupos) {
  const { sessao } = m;
  const combate = sessao.combate ?? {};
  const out = [];
  for (const c of sessao.condicoes ?? []) {
    const f = fichaDaCondicao(c.nome, c.forca);
    out.push({ chave: `condicao:${c.id}`, tipo: "condicao", classe: "condicao", nome: c.nome, origem: { rotulo: "Condição", detalhe: f.forcaLabel ?? "", curta: f.forcaLabel ? `Condição ${f.forcaLabel}` : "Condição" }, rodadas: c.rodadas ?? null, cond: c, ficha: f, consulta: `condicao:${c.nome}` });
  }
  for (const b of sessao.buffs ?? []) {
    if (ehRegistro(b)) {
      out.push({
        chave: `rec:${b.id}`, tipo: "registro", classe: "recebido", nome: b.origemNome, reg: b,
        origem: { rotulo: TIPO_ROTULO[b.tipoFonte] ?? "Recebido", detalhe: b.aplicadoPor ?? "", curta: b.aplicadoPor ? `De ${b.aplicadoPor}` : "Registrado" },
        rodadas: b.rodadas ?? null, semNumero: !(b.beneficios ?? []).some((x) => x.canal && Number(x.valor)),
      });
    } else if (!b.gerado) {
      const semNumero = !b.canal || !String(b.expr ?? "").trim();
      out.push({ chave: `buff:${b.id}`, tipo: "buff", classe: "recebido", nome: b.nome, origem: { rotulo: b.aplicadoPor ? "Recebido" : "Registrado", detalhe: b.aplicadoPor ?? "", curta: b.aplicadoPor ? `De ${b.aplicadoPor}` : "Registrado" }, rodadas: b.rodadas ?? null, buff: b, semNumero });
    }
  }
  for (const g of grupos) {
    if (g.sustentacao) {
      for (const e of g.estados) {
        const v = combate[e.id];
        if (!v) continue;
        const nome = (e.opcoes ?? []).find((o) => o.id === v)?.label ?? "Feitiço";
        out.push({ chave: `sust:${e.id}`, tipo: "sustentado", classe: "proprio", nome, origem: { rotulo: "Feitiço", curta: `Sustentado · ${e.label.replace("Sustentação", "Vaga")}` }, estado: e, feiticoId: v, grupo: g, consulta: `feitico:${v}` });
      }
      continue;
    }
    if (!grupoLigado(g, combate, sessao)) continue;
    out.push({ chave: g.chave, tipo: "grupo", classe: g.recebido ? "recebido" : "proprio", nome: g.nome, origem: g.origem, grupo: g, exemplo: exemploDoGrupo(g), consulta: g.item?.chave ?? `estado:${g.raiz.id}` });
  }
  if ((sessao.exaustao ?? 0) > 0) out.push({ chave: "exaustao", tipo: "exaustao", classe: "condicao", nome: "Exaustão", origem: { rotulo: "Contador", curta: "Contador" }, nivel: sessao.exaustao });
  return out.sort((a, b) => ORDEM_ATIVO[a.classe] - ORDEM_ATIVO[b.classe] || a.nome.localeCompare(b.nome, "pt"));
}

/** A sessão SEM um ativo, para a conta "com ele contra sem ele". */
export function sessaoSem(a, sessao) {
  if (a.tipo === "grupo") return { ...sessao, combate: { ...sessao.combate, ...Object.fromEntries(a.grupo.estados.map((e) => [e.id, padraoDe(e)])) } };
  if (a.tipo === "sustentado") return { ...sessao, combate: { ...sessao.combate, [a.estado.id]: null } };
  if (a.tipo === "condicao") return { ...sessao, condicoes: sessao.condicoes.filter((x) => x.id !== a.cond.id) };
  if (a.tipo === "buff") return { ...sessao, buffs: sessao.buffs.filter((x) => x.id !== a.buff.id) };
  if (a.tipo === "registro") return { ...sessao, buffs: sessao.buffs.filter((x) => x.id !== a.reg.id) };
  return null;
}

/** O que cada ativo está dando, e quem cobre quem quando nada muda. */
export function consequencias(ficha, sessao, derived, ativos) {
  return comAddons(ficha, () => {
    const out = new Map();
    const sem = new Map();
    for (const a of ativos) {
      const s = sessaoSem(a, sessao);
      if (!s) { out.set(a.chave, []); continue; }
      const d = derivarCom(ficha, s);
      sem.set(a.chave, s);
      out.set(a.chave, compararTudo(derived, d));
    }
    /* Nada muda sem ele? Procura quem já dá o mesmo: sem os dois, algo muda. */
    const cobertos = new Map();
    for (const a of ativos) {
      if (a.tipo !== "grupo" || (out.get(a.chave) ?? []).length) continue;
      for (const h of ativos) {
        if (h === a || h.tipo !== "grupo" || !sem.has(h.chave)) continue;
        const semH = sem.get(h.chave);
        const semAmbos = sessaoSem(a, semH);
        if (compararTudo(derivarCom(ficha, semH), derivarCom(ficha, semAmbos)).length) { cobertos.set(a.chave, h.nome); break; }
      }
    }
    return { porAtivo: out, cobertos };
  });
}

/* O canal do motor e a marca da comparação têm nomes diferentes. */
const CANAL_PARA_MARCA = { defesa: "defesa", bonusAcerto: "acerto", danoBonus: "dano", rdGeral: "rdGeral", rdFisico: "rdFisico", movimento: "movimento", iniciativa: "iniciativa", atencao: "atencao" };
const ROTULO_MARCA = { defesa: "Defesa", acerto: "Acerto", dano: "Dano", rdGeral: "RD Geral", rdFisico: "RD Física", movimento: "Movimento", iniciativa: "Iniciativa", atencao: "Atenção" };
const txt = (v) => `${v > 0 ? "+" : "−"}${Math.abs(v)}`;

/**
 * O que a FONTE vale, e não o que se perde sem ela. Numa disputa (Feitiços
 * entre si, a mesma habilidade repetida), "com contra sem" mostra a diferença
 * para o segundo colocado: o Véu Protetor de +6 aparecia como +5 porque, sem
 * ele, a Pele de Ferro daria +1. A linha diz +6, e o detalhe explica a troca.
 *   vale    { marca: { chave, rotulo, valor, texto } } que a fonte PÕE na conta
 *   coberto nome de quem vale no lugar, quando nada dela soma
 */
/* O recebido que a mesma habilidade da própria ficha já cobre. */
export const COBERTO_PELA_PROPRIA = "propria";
export function contribuicao(a, derived, analise, emGrupos = true) {
  const vale = new Map();
  const empates = [];
  let coberto = null;
  if (a.tipo === "registro") {
    const an = analise?.[a.reg.id] ?? {};
    for (const [canal, x] of Object.entries(an)) {
      const chave = CANAL_PARA_MARCA[canal] ?? canal;
      const v = x.status === "excede" ? x.delta : ["soma", "substitui", "presumido", "empata"].includes(x.status) ? x.valor : null;
      if (v != null) vale.set(chave, { chave, rotulo: ROTULO_MARCA[chave] ?? canal, valor: v, texto: txt(v) });
      if (x.status === "empata") empates.push({ canal, com: x.vencedor });
      else if (v == null && !coberto) coberto = x.vencedor?.nome ?? (x.status === "coberto" ? COBERTO_PELA_PROPRIA : null);
    }
    if (vale.size) coberto = null;
    return { vale, coberto, empates };
  }
  if (a.tipo === "grupo" || a.tipo === "sustentado") {
    const det = (derived.efeitos?.detalhes ?? []).filter((d) => d.nome === a.nome && d.exclusivo);
    const disputas = disputasPorFonte(derived, emGrupos).get(a.nome) ?? [];
    for (const d of det) {
      const chave = CANAL_PARA_MARCA[d.canal];
      if (!chave) continue;
      const empate = disputas.find((x) => x.canal === d.canal && x.alvo === (d.alvo ?? null) && x.status === "empata");
      /* No empate, os dois valem o mesmo: a linha mostra o valor dos dois. */
      if (!d.suplantado || empate) vale.set(chave, { chave, rotulo: ROTULO_MARCA[chave], valor: d.valor, texto: txt(d.valor) });
      if (empate) empates.push({ canal: d.canal, com: empate.com });
    }
    const perdas = disputas.filter((x) => x.status === "perde");
    if (det.length && !vale.size && perdas.length) coberto = perdas[0].vencedor?.nome ?? null;
  }
  return { vale, coberto, empates };
}

/** Por ativo próprio: os valores disputados, com `perde` e `empata` separados. */
export function disputasDosAtivos(ativos, derived, emGrupos = true) {
  const todas = disputasPorFonte(derived, emGrupos);
  const out = new Map();
  for (const a of ativos) {
    if (a.tipo !== "grupo" && a.tipo !== "sustentado") continue;
    const p = todas.get(a.nome);
    if (p?.length) out.set(a.chave, p);
  }
  return out;
}

/* ============================================================
   PV TEMPORÁRIO: concede, registrado, resta
   ============================================================
   Três números que a rodada 8 misturava:
     concede   o que a habilidade dá, CALCULADO pelo motor agora
     registro  se a concessão desta ativação (ou desta rodada) já foi para
               a Vida, guardado em `mesa.pvConcessoes`, e não no pote
     resta     o que sobra no pote da sessão (`pvTempFontes`) daquela fonte
   Consumir 18 de 30 deixa 12 e NÃO reabre a concessão. Uma concessão nova só
   segue a regra da habilidade (`PV_TEMP` em exemplos.js): por uso, depois de
   encerrar e ativar de novo, ou por rodada. O Invencível sob o Sol renova a
   Postura da Terra sozinho, e aí não existe botão: a reserva é da ficha.
   ⚠ A ORIGEM vem do detalhe do motor (`d.origem`, o id do catálogo). O
   Invencível que incorpora a Postura da Terra conta como o MESMO benefício,
   com UMA reserva só: ver `umaReserva` e `depoisDaVirada`, logo abaixo.
   ============================================================ */
export function beneficiosPvTemp(m) {
  const combate = m.sessao.combate ?? {};
  const pote = m.sessao.pvTempFontes ?? {};
  const concessoes = m.mesa.pvConcessoes ?? {};
  const invencivel = !!combate.invencivelSobOSol;
  const out = new Map();
  for (const d of m.derived.efeitos?.detalhes ?? []) {
    if (d.canal !== "pvTemporario" || d.suplantado || !d.valor) continue;
    const regra = PV_TEMP[d.origem] ?? { beneficio: d.origem ?? d.nome, fonte: d.nome, regra: "uso", texto: "Regra de concessão não revisada", naoRevisada: true };
    const chave = regra.beneficio;
    if (!out.has(chave)) {
      const pelaFicha = chave === "terra" && invencivel;
      const fonte = pelaFicha ? FONTE_TERRA_INVENCIVEL : regra.fonte;
      const reg = concessoes[chave] ?? null;
      const podeRegistrar = !pelaFicha && (regra.regra === "rodada" ? !reg || reg.rodada < m.sessao.rodada : !reg);
      /* O que resta é o do BENEFÍCIO, em qualquer das fontes dele. */
      const resta = (FONTES_DO_BENEFICIO[chave] ?? [fonte]).reduce((s, f) => s + (pote[f] ?? 0), 0);
      out.set(chave, {
        beneficio: chave, fonte, regra: pelaFicha ? "ficha" : regra.regra, textoRegra: pelaFicha ? "A ficha renova a cada rodada, pelo Invencível sob o Sol" : regra.texto,
        naoRevisada: !!regra.naoRevisada, concede: 0, origens: [], registro: reg, resta, podeRegistrar,
        dono: DONO_PV[d.origem] ?? null,
      });
    }
    const b = out.get(chave);
    b.concede += d.valor;
    b.origens.push(d.origem);
  }
  return out;
}
/* ---------------- uma reserva por benefício ----------------
   O pote da sessão SOMA as fontes (`pvTempTotal`). A Postura da Terra chega por
   dois nomes: "Postura da Terra", quando o jogador registra, e o que o motor
   escreve quando o Invencível sob o Sol a renova. Os dois são o MESMO
   benefício, e por isso nunca podem existir juntos no pote.
   Uma concessão nova (registrar, ou a renovação do Invencível na virada) fica
   com o MAIOR entre ela e o que resta, que é a regra do próprio motor para a
   mesma fonte (`Math.max` em `avancaInvencivelSobOSol`). O que foi consumido
   continua consumido até uma concessão nova. */
export const FONTES_DO_BENEFICIO = { terra: ["Postura da Terra", FONTE_TERRA_INVENCIVEL] };

/** A sessão com uma reserva só do benefício, na `fonteAlvo`. `concessao` é o valor de uma concessão NOVA, ou 0. */
export function umaReserva(sessao, beneficio, fonteAlvo, concessao = 0) {
  const fontes = FONTES_DO_BENEFICIO[beneficio] ?? [fonteAlvo];
  const pote = { ...(sessao.pvTempFontes ?? {}) };
  const resta = Math.max(0, ...fontes.map((f) => pote[f] ?? 0));
  for (const f of fontes) delete pote[f];
  const valor = Math.max(resta, concessao);
  if (valor > 0) pote[fonteAlvo] = valor;
  return { ...sessao, pvTempFontes: pote };
}

/**
 * Dados antigos (E3, 2026-10-16): as duas fontes da Terra no pote (a registrada à mão e a do Invencível) são UMA
 * reserva. Fica o MAIOR dos saldos, na fonte que vale agora (a do Invencível com ele ligado), e nunca a SOMA: o saldo
 * somado não é uma concessão nova, e dois +30 não viram +60. Devolve a MESMA mesa quando não há o que juntar, e não toca
 * a Vida, o registro da concessão (`pvConcessoes`) nem outro benefício.
 */
export function normalizaReservas(mesa) {
  const s = mesa?.sessao;
  const pote = s?.pvTempFontes;
  if (!pote) return mesa;
  if (FONTES_DO_BENEFICIO.terra.filter((f) => (pote[f] ?? 0) > 0).length < 2) return mesa;
  const alvo = s.combate?.invencivelSobOSol ? FONTE_TERRA_INVENCIVEL : "Postura da Terra";
  return { ...mesa, sessao: umaReserva(s, "terra", alvo, 0) };
}

/**
 * Depois da virada de rodada. Se o Invencível sob o Sol continuou, o motor
 * acabou de renovar a Postura da Terra na fonte dele: é uma concessão nova, a
 * da rodada. A reserva registrada à mão antes dele é o mesmo benefício e se
 * junta a ela, e a concessão fica anotada como da ficha, nesta rodada. Sem
 * essa anotação, encerrar o Invencível e assumir a Terra de novo na mesma
 * rodada ofereceria uma segunda concessão que a regra não dá.
 */
export function depoisDaVirada(mesa) {
  const s = mesa.sessao;
  const renovada = s.combate?.invencivelSobOSol ? s.pvTempFontes?.[FONTE_TERRA_INVENCIVEL] ?? 0 : 0;
  if (!renovada) return mesa;
  return {
    ...mesa,
    sessao: umaReserva(s, "terra", FONTE_TERRA_INVENCIVEL),
    pvConcessoes: { ...(mesa.pvConcessoes ?? {}), terra: { valor: renovada, fonte: FONTE_TERRA_INVENCIVEL, rodada: s.rodada, pelaFicha: true, ts: Date.now() } },
  };
}

/* Quem é a linha dona de cada origem de PV Temporário, pelo id do item. */
export const DONO_PV = {
  cmb_espirito_de_luta: "cmb_espirito_de_luta", cmb_espirito_incansavel: "cmb_espirito_de_luta",
  cmb_postura_da_terra: "cmb_assumir_postura", api_invencivel_sob_o_sol: "api_invencivel_sob_o_sol", cobrir_se: "cobrir_se",
};
/**
 * As concessões de PV Temporário POR USO de uma habilidade esquecidas, no registro `pvConcessoes` da mesa (a por rodada
 * continua anotada). Um uso novo (Encerrar e Reativar, ou Usar Novamente) é uma concessão nova. O que já está no pote
 * fica: quem junta é o `umaReserva`, com o MAIOR entre o saldo e a concessão nova, e nunca a soma.
 */
export function semConcessoesDeUso(pvConcessoes, itemId) {
  const beneficios = new Set(Object.entries(PV_TEMP).filter(([origem, x]) => DONO_PV[origem] === itemId && x.regra !== "rodada").map(([, x]) => x.beneficio));
  return Object.fromEntries(Object.entries(pvConcessoes ?? {}).filter(([k]) => !beneficios.has(k)));
}
/** O benefício de PV Temporário de um ativo, pela dona da origem. */
export function pvDoAtivo(a, beneficios) {
  const id = a.grupo?.item?.id;
  if (!id) return null;
  for (const b of beneficios.values()) if (b.dono === id) return b;
  return null;
}

/* A sessão depois da próxima virada, pelo MOTOR (`proximaRodada`), sobre uma
   cópia: nada é gravado. Uma vez por sessão (a mesma sessão é lida por vários
   cartões no mesmo desenho). */
const VIRADAS = new WeakMap();
export function viradaDoMotor(m) {
  const s = m.mesa?.sessao ?? m.sessao;
  if (!s || !m.derived) return null;
  if (!VIRADAS.has(s)) VIRADAS.set(s, Sessao.proximaRodada(s, m.derived).sessao);
  return VIRADAS.get(s);
}

/* ---------------- custo, duração e atenção de um ativo ---------------- */
/* Âmbar só para o que pede decisão agora: cobrança automática que vem, Exaustão
   e regra pendente. Duração e custo rotineiro são texto neutro. */
export function detalhesDoAtivo(a, m) {
  const combate = m.sessao.combate ?? {};
  const out = { duracao: null, contador: null, custo: null, atencao: [], naMesa: [] };
  if (a.tipo === "condicao" || a.tipo === "buff" || a.tipo === "registro") {
    out.duracao = a.rodadas == null ? null : a.rodadas === 1 ? "Última Rodada" : `${a.rodadas} Rodadas`;
  }
  if (a.tipo === "sustentado") {
    const at = (m.derived.auxiliaresAtivos?.ativos ?? []).find((x) => x.id === a.feiticoId);
    if (at?.sustentacaoPE) out.custo = { texto: `${at.sustentacaoPE} PE por Rodada`, cobra: false };
    out.naMesa.push({ rotulo: "Termina", texto: "Quando a vaga é liberada ou a manutenção deixa de ser paga" });
    const op = (a.estado?.opcoes ?? []).find((x) => x.id === a.feiticoId);
    const trava = typeof op?.bloqueio === "function" ? op.bloqueio(m.derived, true) : null;
    if (trava) out.atencao.push(trava);
  }
  if (a.tipo === "grupo") {
    const ex = a.exemplo;
    for (const e of a.grupo.estados) {
      const v = combate[e.id];
      if (!estaLigado(e, v)) continue;
      /* Ligado, a trava do Feitiço Permutativo é só aviso: o número caiu depois (uma condição) e o Feitiço segue ligado. */
      if (typeof e.bloqueio === "function") { const t = e.bloqueio(m.derived, true); if (t && !out.atencao.includes(t)) out.atencao.push(t); }
      if (e.id === "invencivelSobOSol") {
        const r = Math.max(1, Math.trunc(Number(combate.invencivelRodadas) || 1));
        out.contador = `Rodada ${r} de 4`;
        out.custo = { texto: "4 PE por Rodada", cobra: true };
        /* ⚠ CORRIGIDO EM 2026-10-14: a previsão olhava o PE de AGORA. Na virada,
           a casca de PE do gatilho `rodada` volta ao teto ANTES da cobrança, e
           com zero PE o Invencível pode continuar. Quem decide é a virada do
           próprio motor, rodada sobre uma cópia (`viradaDoMotor`). */
        const prox = viradaDoMotor(m);
        if (prox?.combate?.invencivelSobOSol) out.atencao.push("Cobra 4 PE na Próxima Rodada");
        else out.atencao.push("Encerra na Próxima Rodada");
        if (combate.invencivelPendenteExaustao) out.atencao.push("Exaustão no Fim da Rodada");
        continue;
      }
      if (e.feiticoId) {
        const f = m.pacote.rep.porChave.get(`feitico:${e.feiticoId}`);
        const c = Math.trunc(Number(f?.ref?.custoPE) || 0);
        if (c && !out.custo) out.custo = { texto: `${c} PE`, cobra: false };
        continue;
      }
      const custo = custoDe(e, v);
      if (custo != null && !out.custo) out.custo = { texto: `${custo} PE`, cobra: false };
      if (e.umaVezPorRodada && Sessao.estadoUsadoNestaRodada(m.sessao, e.id)) out.atencao.push("Usado Nesta Rodada");
    }
    if (!out.custo && ex?.custoCurto) {
      const cc = ex.custoCurto;
      if (typeof cc === "string") out.custo = { texto: cc, cobra: false };
      else {
        const ligado = Object.keys(cc).filter((k) => k !== "padrao" && combate[k]).pop();
        out.custo = { texto: cc[ligado] ?? cc.padrao, cobra: false };
      }
    }
    if (!out.custo && ex?.custoDoValor) {
      const e = a.grupo.controles[0].estados[0];
      const n = Math.trunc(Number(combate[e.id]) || 0);
      if (n) out.custo = { texto: `${n} PE`, cobra: false };
    }
    if (!out.custo && ex?.custoDoEstado) {
      const partes = partesDoCusto(a.grupo, combate, ex);
      const n = (partes ?? []).reduce((s, p) => s + p.gasto, 0);
      if (n) out.custo = { texto: `${n} PE`, cobra: false };
    }
    if (ex?.quando) out.naMesa.push({ rotulo: "Quando", texto: ex.quando });
    if (ex?.duracao && !out.contador) out.naMesa.push({ rotulo: "Duração", texto: ex.duracao });
    if (ex?.usos) out.naMesa.push({ rotulo: "Usos", texto: ex.usos });
  }
  if (a.tipo === "registro" && (a.reg.beneficios ?? []).some((b) => b.canal && Number(b.valor)) && !(a.reg.tipoFonte === "feitico" || (a.reg.tipoFonte === "catalogo" && a.reg.origemId) || a.reg.somaPresumida)) {
    out.atencao.push("Regra de Acúmulo Pendente");
  }
  if (a.tipo === "exaustao") out.naMesa.push({ rotulo: "Efeito", texto: "A penalidade de cada nível ainda não tem fonte no Afty e é de mesa" });
  return out;
}

export { estaLigado, padraoDe, compararSaldo, maxDe, derivarCom };

/* ============================================================
   ESTATÍSTICAS DO CABEÇALHO, CONFIGURÁVEIS POR PERSONAGEM (fechamento do G2, 2026-10-16)
   ============================================================
   O cabeçalho mostra as estatísticas que `statsDaFicha` (v2) devolve, na ordem dele, e manda o que não cabe para "+N". Aqui o jogador escolhe
   O QUE aparece e EM QUE ORDEM. É só apresentação: nenhum valor, fonte, bônus ou efeito muda, e os recursos (Vida, Energia e Alma) e os controles
   de combate (Em Combate, Rodada, Efeitos) não são estatísticas e não entram nesta lista.

   A PREFERÊNCIA mora na UI da mesa do personagem (`mesa.ui.estatisticas`, gravada com ela): { ordem: [ids], ocultas: [ids] }. `null` (ou nada)
   é "nunca configurou", e vale a apresentação de hoje, sem tocar o cabeçalho padrão. Restaurar padrão apaga a preferência.

   TRATAMENTO SEGURO, tudo aqui e sem exceção:
     - a preferência lida de fora passa por `normalizaPreferencia`: o que não for lista de textos é descartado, os repetidos somem, e o resultado
       nunca derruba a tela;
     - um id guardado que a ficha não tem agora (a RD Física some quando é 0) é IGNORADO na tela e MANTIDO na preferência, no lugar em que estava:
       se a estatística voltar, volta ao mesmo lugar;
     - um id que a ficha tem e a preferência nunca viu (uma estatística nova) entra no fim da ordem, visível, sem duplicar.
   Funções puras, sem React.
   ============================================================ */

const MAX = 64;
const idsDe = (v) => {
  const vistos = new Set();
  const out = [];
  if (!Array.isArray(v)) return out;
  for (const x of v) {
    if (typeof x !== "string" || !x || x.length > 40 || vistos.has(x)) continue;
    vistos.add(x);
    out.push(x);
    if (out.length >= MAX) break;
  }
  return out;
};

/** A preferência já validada, ou `null`. Aceita qualquer coisa vinda de fora. */
export function normalizaPreferencia(bruto) {
  if (!bruto || typeof bruto !== "object" || Array.isArray(bruto)) return null;
  const ordem = idsDe(bruto.ordem);
  const ocultas = idsDe(bruto.ocultas);
  if (!ordem.length && !ocultas.length) return null;
  return { ordem, ocultas };
}

/** A ordem COMPLETA de agora: a guardada (com os ids que a ficha não tem, nos lugares deles) mais, no fim, o que a preferência nunca viu. */
function ordemCompleta(stats, pref) {
  const agora = stats.map((s) => s.id);
  const guardada = pref?.ordem ?? [];
  const novos = agora.filter((id) => !guardada.includes(id));
  return [...guardada, ...novos];
}

/**
 * Aplica a preferência às estatísticas da ficha.
 *   `todas`    as estatísticas que a ficha tem agora, na ordem da preferência, cada uma com `visivel` (é o que a configuração lista)
 *   `visiveis` só as que aparecem, na mesma ordem (é o que a faixa e o "+N" usam: o ocultado NUNCA volta como excesso de largura)
 *   `padrao`   não há preferência: a apresentação de hoje
 */
export function aplicaPreferencia(stats, bruto) {
  const pref = normalizaPreferencia(bruto);
  if (!pref) return { todas: stats.map((s) => ({ ...s, visivel: true })), visiveis: stats, padrao: true };
  const porId = new Map(stats.map((s) => [s.id, s]));
  const ocultas = new Set(pref.ocultas);
  const todas = ordemCompleta(stats, pref).filter((id) => porId.has(id)).map((id) => ({ ...porId.get(id), visivel: !ocultas.has(id) }));
  return { todas, visiveis: todas.filter((s) => s.visivel).map(({ visivel, ...s }) => s), padrao: false };
}

const comOrdem = (stats, pref, novaOrdemAgora) => {
  /* os ids que a ficha não tem agora ficam onde estavam: só os de agora trocam de lugar entre si */
  const agora = new Set(stats.map((s) => s.id));
  const base = ordemCompleta(stats, pref);
  const fila = [...novaOrdemAgora];
  return base.map((id) => (agora.has(id) ? fila.shift() : id));
};

/** Mostra ou oculta uma estatística. Devolve a preferência nova (a de fora não é alterada). */
export function alternaVisivel(stats, bruto, id) {
  const pref = normalizaPreferencia(bruto);
  if (!stats.some((s) => s.id === id)) return pref;
  const ordem = comOrdem(stats, pref, aplicaPreferencia(stats, pref).todas.map((s) => s.id));
  const ocultas = new Set(pref?.ocultas ?? []);
  if (ocultas.has(id)) ocultas.delete(id); else ocultas.add(id);
  return normalizaPreferencia({ ordem, ocultas: [...ocultas] });
}

/** Move uma estatística `delta` casas (−1 sobe, +1 desce) entre as que a ficha tem agora. Nos extremos, nada muda. */
export function move(stats, bruto, id, delta) {
  const pref = normalizaPreferencia(bruto);
  const atual = aplicaPreferencia(stats, pref).todas.map((s) => s.id);
  const de = atual.indexOf(id);
  const para = de + delta;
  if (de < 0 || para < 0 || para >= atual.length) return pref;
  const nova = [...atual];
  nova.splice(para, 0, nova.splice(de, 1)[0]);
  return normalizaPreferencia({ ordem: comOrdem(stats, pref, nova), ocultas: pref?.ocultas ?? [] });
}

/** Restaurar padrão: nenhuma preferência. */
export const restauraPadrao = () => null;

/**
 * ============================================================
 * AS OPERAÇÕES DA ABA EFEITOS, PURAS SOBRE A MESA
 * ============================================================
 * A "mesa" é a visão da SESSÃO da Ficha que `sessao-g2.js` monta (`daSessao`) e desfaz (`paraSessao`): a sessão com o registro
 * das operações (eventos, ativações, usos novos, concessões de PV e encerrados). Cada função recebe a mesa e devolve `{ mesa, erro? }`,
 * sem tocar em nada fora dela, e o adaptador a roda DENTRO de `atualiza`, sobre a sessão que estiver valendo (atômica). O evento só
 * nasce depois do sucesso: quem recusa devolve a mesa de antes, sem evento.
 * ============================================================
 */
import * as Sessao from "../ficha-sessao";
import { usarEfeitoEspecializacao } from "../ficha-especializacoes";
import { marcasDoGolpe } from "../../afty-golpe-especial";
import { semConcessoesDeUso, umaReserva, beneficiosPvTemp } from "./efeitos-dados";
import { PROPRIEDADES, sessaoComMarcas } from "./g2-golpe";
import { alterarEstado, comEvento, energiaDisponivel, gastoManual } from "./mesa-verbos";
import { uid } from "./util";

/* ============================================================
   ESTADOS COM CONFIRMAÇÃO: TUDO OU NADA (Catálogo, 2026-10-15)
   ============================================================
   As operações que uma Preparação confirma, como funções PURAS da mesa. A
   tela roda a mesma função na mesa de agora antes de confirmar (a prova e a
   prévia), e o `setMesa` roda de novo sobre a mesa que estiver valendo:
     - `esperado` é o valor de PARTIDA de cada estado, o que a tela mostrou.
       Se a sessão mudou (a outra apresentação, ou o segundo clique de um
       clique duplo), nada é aplicado.
       ⚠ Ligar de novo o que já está ligado NÃO é inofensivo: no Invencível
       sob o Sol, o motor trata como desligar (`alteraEstadoCombate`), e a
       Exaustão fica devida;
     - um estado que já está no valor pedido não é reaplicado;
     - qualquer recusa do motor devolve a mesa de antes, sem estado aplicado
       pela metade;
     - `tirarEncerrado` sai dos Encerrados na MESMA operação.
   ============================================================ */
/** O mesmo valor para o estado? A lista do `multi` vale como conjunto. */
export function mesmoValor(e, a, b) {
  if (e.tipo === "multi") {
    const x = Array.isArray(a) ? a : [];
    const y = Array.isArray(b) ? b : [];
    return x.length === y.length && x.every((id) => y.includes(id));
  }
  if (e.tipo === "faixa") return Math.trunc(Number(a) || 0) === Math.trunc(Number(b) || 0);
  if (e.tipo === "bool") return !!a === !!b;
  return (a ?? null) === (b ?? null);
}

const semEncerrado = (mesa, chave) => (chave
  ? { ...mesa, ui: { ...mesa.ui, encerrados: (mesa.ui.encerrados ?? []).filter((y) => y.chave !== chave) } }
  : mesa);
const confere = (mm, esperado, lista) => {
  const agora = mm.sessao.combate ?? {};
  if (esperado.every(({ estado, valor }) => mesmoValor(estado, agora[estado.id], valor))) return null;
  const repetido = lista.length > 0 && lista.every(({ estado, valor }) => mesmoValor(estado, agora[estado.id], valor));
  return repetido ? "Já Aplicado" : "A Ficha Mudou Antes de Confirmar";
};

/** Vários estados de uma vez, pelo `alterarEstado` (o mesmo verbo do `estadoMuda`). Sem gasto: o custo à mão continua à mão.
 *  `novoUso` (USAR NOVAMENTE, 2026-10-16): um uso novo de um efeito ativo, que vale até com o MESMO valor. O estado não
 *  prova que o clique já passou, e por isso o contador `mesa.reusos[chave]` é o que se confere e se avança, na mesma
 *  operação dos estados. A concessão de PV Temporário do uso anterior deixa de estar registrada (a nova se oferece), e o
 *  pote fica como está: quem junta é o `umaReserva`, com o MAIOR entre o saldo e a concessão nova. */
export function aplicaEstados(mm, { lista = [], esperado = [], tirarEncerrado = null, usos = null, novoUso = null, travas = [] }, { derived, calculo = null }) {
  const reusosAgora = novoUso ? Math.max(0, Math.trunc(Number(mm.reusos?.[novoUso.chave]) || 0)) : 0;
  if (novoUso && reusosAgora !== novoUso.esperado) return { mesa: mm, erro: "A Ficha Mudou Antes de Confirmar" };
  const mudouAntes = confere(mm, esperado, lista);
  if (mudouAntes) return { mesa: mm, erro: mudouAntes };
  /* A trava do Feitiço Permutativo (`bloqueio(derived, ligado)`, do motor) é lida DE NOVO aqui, no derive da mesa que está valendo
     agora, e não no da tela: o que a prévia mostrou como livre pode ter mudado. Nada é aplicado se alguma trava segura. */
  if (travas.length && calculo) {
    const d = calculo(mm.sessao);
    for (const { estado, opcao = null } of travas) {
      const alvo = opcao ? (estado.opcoesVisiveis ?? estado.opcoes ?? []).find((x) => x.id === opcao) : estado;
      const t = typeof alvo?.bloqueio === "function" ? alvo.bloqueio(d, false) : null;
      if (t) return { mesa: mm, erro: t };
    }
  }
  let out = mm;
  let mudou = false;
  for (const { estado, valor } of lista) {
    if (mesmoValor(estado, out.sessao.combate?.[estado.id], valor)) continue;
    const r = alterarEstado(out, estado, valor, derived);
    if (r.recusado) return { mesa: mm, erro: `${estado.label} não mudou` };
    out = r.mesa;
    mudou = true;
  }
  if (!mudou && !novoUso) return { mesa: mm, erro: "Nada Mudou" };
  if (novoUso) {
    out = { ...out, reusos: { ...(out.reusos ?? {}), [novoUso.chave]: reusosAgora + 1 }, pvConcessoes: semConcessoesDeUso(out.pvConcessoes, novoUso.itemId) };
  }
  /* E3: os usos que a ativação gasta (o contador real do motor, na MESMA operação dos estados): conferidos contra o
     que a tela mostrou, e nada é gasto se um dos dois falha. Sem contador no motor, nada a gastar. */
  if (usos) {
    const u = derived?.usosHabilidades?.[usos.itemId] ?? null;
    if (u) {
      const gastos = Sessao.usosGastosDe(out.sessao, u.chave);
      if (gastos !== usos.esperado) return { mesa: mm, erro: "A Ficha Mudou Antes de Confirmar" };
      if (gastos >= u.max) return { mesa: mm, erro: "Sem Usos Restantes" };
      const gasta = Sessao.marcaUso(out.sessao, u, 1);
      if (gasta === out.sessao) return { mesa: mm, erro: "Nada Mudou" };
      out = { ...out, sessao: gasta };
    }
  }
  return { mesa: semEncerrado(out, tirarEncerrado) };
}

/** Um estado E o gasto dele (o piloto do Ataque Concentrado), com a mesma conferência de partida. */
export function pagaEstado(mm, { estado, valor, custo = 0, motivo = null, esperado, tirarEncerrado = null }, { derived }) {
  if (esperado !== undefined) {
    const mudouAntes = confere(mm, [{ estado, valor: esperado }], [{ estado, valor }]);
    if (mudouAntes) return { mesa: mm, erro: mudouAntes };
  }
  const ligado = alterarEstado(mm, estado, valor, derived);
  if (ligado.recusado) return { mesa: mm, erro: `${estado.label} não mudou` };
  let out = ligado.mesa;
  if (custo) {
    const pago = gastoManual(out, custo, motivo, derived);
    if (pago.erro) return { mesa: mm, erro: pago.erro };
    out = pago.mesa;
  }
  return { mesa: semEncerrado(out, tirarEncerrado) };
}

/* ============================================================
   REGISTRAR USO: O CONTADOR REAL DO MOTOR (E2, 2026-10-15)
   ============================================================
   Gasta UM uso do contador que o motor já tem (`derived.usosHabilidades`, a
   sessão guarda os GASTOS em `usos["hab:<id>"]`) e anota o evento. Função
   PURA da mesa, como as de cima: a tela roda a mesma na mesa de agora (a prova),
   e o `setMesa` roda de novo sobre a mesa que estiver valendo.
     - `esperado` é o número de usos gastos que a tela mostrou. Se a sessão
       andou (o segundo clique de um clique duplo), nada é gasto de novo;
     - o verbo é o do MOTOR: `marcaUso` (Indomável) ou `usarEfeitoEspecializacao`
       (Surto de Ação: uma vez por rodada e uma ação comum a mais). Sem contador
       no motor (Ataque Extra) não há uso a gastar: só o evento;
     - o PE é à mão: aqui só se confere que há Energia. Nada é descontado.
   ⚠ `ficha-especializacoes.js` tem mudanças locais ainda sem commit no
   repositório: o hash dele vai nas evidências. */
const inteiroUso = (v) => Math.max(0, Math.trunc(Number(v) || 0));
export function registraUso(mm, { chave, nome, itemId, esperado = null, custoPE = 0 }, { derived }) {
  const s0 = mm.sessao;
  const falta = Math.max(0, inteiroUso(custoPE) - energiaDisponivel(s0));
  if (falta) return { mesa: mm, erro: `Faltam ${falta} PE` };
  const u = derived?.usosHabilidades?.[itemId] ?? null;
  let s = s0;
  let usos = null;
  if (u) {
    const gastos = Sessao.usosGastosDe(s0, u.chave);
    if (esperado != null && gastos !== esperado) return { mesa: mm, erro: "A Ficha Mudou Antes de Registrar" };
    if (gastos >= u.max) return { mesa: mm, erro: "Sem Usos Restantes" };
    s = itemId === "cmb_surto_de_acao" ? usarEfeitoEspecializacao(s0, derived, itemId) : Sessao.marcaUso(s0, u, 1);
    if (s === s0) return { mesa: mm, erro: itemId === "cmb_surto_de_acao" ? "Já Usado Nesta Rodada" : "Nada Mudou" };
    usos = { max: u.max, restam: u.max - Sessao.usosGastosDe(s, u.chave) };
  }
  const mesa = comEvento({ ...mm, sessao: Sessao.aparaSessao(s, derived) }, { tipo: "uso", nome, chave, ...(usos ? { usos } : {}) });
  return { mesa, usos };
}

/* ============================================================
   O GOLPE ESPECIAL: MONTAR E PAGAR (consolidação ampliada, 2026-10-16)
   ============================================================
   Função PURA da mesa, como as de cima. Aplica as marcas do rascunho e paga o golpe pela FUNÇÃO DA FICHA
   (`pagaGolpeEspecial`, ficha-sessao.js), que é o contrato de quem cobra aqui: o PE pelo `gastaPe` (casca primeiro),
   o Sacrifício como dano, o Preciso pago na rodada e a troca por 6 do Autossuficiente. É uma exceção de cobrança do
   MONTADOR, e não a regra de confirmar: o Ataque Concentrado é outra, e nada se generaliza a partir dela.
   Tudo ou nada, conferido na mesa que estiver valendo:
     - as marcas de partida, a rodada e o custo são os que a tela mostrou (senão a ficha mudou antes de confirmar);
     - `mesa.reusos[chave]` conta os golpes pagos: cada confirmação é um golpe novo, até com as mesmas marcas, e o segundo
       clique de um clique duplo não paga de novo;
     - o pagamento fica no histórico como um gasto (`ativacoes`), desfazível como o gasto manual: devolve o PE, e não
       desfaz as marcas nem o Sacrifício. */
function quemPagouGolpe(antes, depois) {
  const casca = {};
  for (const [nome, v] of Object.entries(antes.peTempFontes ?? {})) {
    const d = v - (depois.peTempFontes?.[nome] ?? 0);
    if (d > 0) casca[nome] = d;
  }
  return { casca, reserva: Math.max(0, antes.peAtual - depois.peAtual) };
}
export function aplicaGolpe(mm, { chave, marcas, esperadoMarcas, seis = false, custoVisto, rodadaVista, golpesVistos }, { derived }) {
  const golpes = Math.max(0, Math.trunc(Number(mm.reusos?.[chave]) || 0));
  if (golpes !== golpesVistos) return { mesa: mm, erro: "A Ficha Mudou Antes de Confirmar" };
  const agora = marcasDoGolpe(mm.sessao);
  if (mm.sessao.rodada !== rodadaVista || PROPRIEDADES.some((p) => agora[p.id] !== esperadoMarcas[p.id])) return { mesa: mm, erro: "A Ficha Mudou Antes de Confirmar" };
  if (!mm.sessao.combate?.ativo) return { mesa: mm, erro: "Pede Em Combate" };
  if (!derived?.golpeEspecial?.disponivel) return { mesa: mm, erro: "Golpe Especial Indisponível" };
  const s = sessaoComMarcas(mm.sessao, marcas);
  const custo = Sessao.custoDoGolpeDaSessao(s, derived, { seis });
  if (!custo.montado) return { mesa: mm, erro: "Nenhuma Propriedade" };
  if (custo.aPagar !== custoVisto) return { mesa: mm, erro: "O Custo Mudou Antes de Confirmar" };
  const falta = custo.aPagar - energiaDisponivel(s);
  if (falta > 0) return { mesa: mm, erro: `Faltam ${falta} PE` };
  const paga = Sessao.pagaGolpeEspecial(s, derived, { seis });
  if (paga === s) return { mesa: mm, erro: "A Ficha Não Aceita Agora" };
  const base = { ...mm, sessao: Sessao.aparaSessao(paga, derived), reusos: { ...(mm.reusos ?? {}), [chave]: golpes + 1 } };
  /* Sem PE a pagar (o Autossuficiente cobriu o custo), não há gasto a desfazer: fica só o registro do golpe. */
  /* O Sacrifício também custa Vida (15 de dano): o histórico diz isso, porque estornar o PE não o desfaz. */
  const vida = (x) => x.hpAtual + Sessao.pvTempTotal(x);
  const dano = Math.max(0, vida(s) - vida(paga));
  if (custo.aPagar <= 0) return { mesa: comEvento(base, { tipo: "info", texto: `Golpe Especial montado sem desconto de PE${dano > 0 ? ` e com ${dano} de dano` : ""}` }) };
  const id = uid();
  const pago = quemPagouGolpe(s, paga);
  const ativacao = { id, tipo: "gasto", nome: "Golpe Especial", custo: custo.aPagar, pago, rodada: s.rodada, desfeita: false, rolagens: [] };
  const out = { ...base, ativacoes: { ...mm.ativacoes, [id]: ativacao } };
  return { mesa: comEvento(out, { tipo: "gasto", ativacaoId: id, nome: ativacao.nome, custo: custo.aPagar, pago, ...(dano > 0 ? { dano } : {}) }) };
}

/* ============================================================
   DESCONTAR A ENERGIA: O ATALHO DE PAGAMENTO DE UM EFEITO (2026-10-16)
   ============================================================
   O Descontar de um custo à mão é um GASTO: subtrai o valor da Energia pelo
   MESMO verbo que o painel geral usa (`gastoManual`, que tira da casca de PE
   temporário primeiro, recusa com "Faltam N PE" e deixa o evento no histórico
   com o motivo, desfazível). Nunca substitui o saldo: Definir é outra operação,
   e continua no editor do cabeçalho. Função PURA da mesa, como as de cima:
     - `energiaVista` é a Energia que a tela mostrou. Se ela mudou (o segundo
       clique de um clique duplo, ou outro painel que já pagou), nada é debitado;
     - o valor é sempre o que será descontado, e nunca o que vai sobrar. */
export function descontaEnergia(mm, { valor, motivo = null, energiaVista = null }, { derived }) {
  const quanto = Math.max(0, Math.trunc(Number(valor) || 0));
  if (!quanto) return { mesa: mm, erro: "Informe o Valor" };
  if (energiaVista != null && energiaDisponivel(mm.sessao) !== energiaVista) return { mesa: mm, erro: "A Energia Mudou Antes de Descontar" };
  const r = gastoManual(mm, quanto, motivo, derived);
  return r.erro ? { mesa: mm, erro: r.erro } : r;
}

/* ============================================================
   REGISTRAR PV TEMPORÁRIO NA VIDA: A REVALIDAÇÃO (E3, 2026-10-16)
   ============================================================
   Função PURA da mesa, como as de cima. O botão "Registrar na Vida" mostra o que
   a tela viu (a concessão, e se já havia registro). Ao clicar, a mesa que estiver
   valendo é conferida de novo, e NADA é concedido se:
     - o registro mudou desde que a tela o mostrou (o segundo clique de um clique
       duplo, ou o outro painel que já registrou);
     - a rodada mudou, ou o motor (derive da sessão de AGORA) já não concede esse
       valor, ou a regra da habilidade não oferece o registro (uma concessão por uso,
       uma por rodada, ou a da ficha, que ninguém registra à mão).
   Consumir o pote depois NÃO reabre a concessão: quem decide é o registro
   (`pvConcessoes`), e não o saldo (30 concedidos, 18 consumidos, 12 restam). A
   reserva é UMA por benefício (`umaReserva`): o maior entre o saldo e a concessão.
   Mexe só em `pvTempFontes` e `pvConcessoes`: a Vida normal fica como está. */
export function registraPv(mm, { beneficio, fonte, concede, registroVisto = null, rodadaVista }, { calculo }) {
  const reg = mm.pvConcessoes?.[beneficio] ?? null;
  if ((reg?.ts ?? null) !== (registroVisto ?? null) || mm.sessao.rodada !== rodadaVista) return { mesa: mm, erro: "A Ficha Mudou Antes de Registrar" };
  const b = beneficiosPvTemp({ derived: calculo(mm.sessao), sessao: mm.sessao, mesa: mm }).get(beneficio);
  if (!b) return { mesa: mm, erro: "Sem Concessão Agora" };
  if (!b.podeRegistrar) return { mesa: mm, erro: "Concessão Já Registrada" };
  if (b.concede !== concede) return { mesa: mm, erro: "A Concessão Mudou" };
  return {
    mesa: {
      ...mm,
      sessao: umaReserva(mm.sessao, beneficio, b.fonte, b.concede),
      pvConcessoes: { ...(mm.pvConcessoes ?? {}), [beneficio]: { valor: b.concede, fonte: b.fonte, rodada: mm.sessao.rodada, ts: Date.now() } },
    },
  };
}

